import React, { useState, useEffect, memo, useMemo, useCallback } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { Checkbox, Button, Tooltip } from 'antd';
import { isEqual, map } from 'lodash';
import { DownOutlined, UpOutlined } from '@ant-design/icons';
import classNames from 'classnames';
import { useHeatmapGesturesType } from 'components/features/heatmaps/hooks';
import {
  gesturesCategory,
  gestureTypesList,
} from 'components/features/heatmaps/constants';
import { useHeatmapContext } from 'components/features/heatmaps/Context/HeatmapContext';
import { compactNotation, preciseNumber } from 'Utils/helpers/commonUtils';
import {
  FilterTitleStyled,
  FilterStyled,
  FilterCascadingSelectStyled,
} from 'components/features/heatmaps/HeatmapDetails/HeatmapStyled';
import { trackPageViews } from 'redux/actions/trackingReport';
import { formattedFilters } from 'Utils/ScreenPageFilter';

const tapsSet = gesturesCategory['Taps'];

const getPercentageSign = (data) => `${data}%`;

const summedPercent = (data) => {
  let dataCopy = '';
  dataCopy = preciseNumber(
    (data
      ?.map(({ percentage }) => percentage || 0)
      .reduce((pV, cV) => pV + cV, 0)), 2
  );
  dataCopy = getPercentageSign(dataCopy);
  return dataCopy;
};

const summedCount = (data) =>
  data?.length &&
  compactNotation(
    data.reduce((pV, cV) => pV.count + cV.count, 0),
    2
  );

  const CategoryItems = memo(
    ({
      title,
      subCategories,
      mainCategories,
      subCategoryByTitle,
      isAllGestures,
      allGestureToggler,
    }) => {
      const dispatch = useDispatch();
      const { urlReducer: {screenname}} = useSelector(state => state);
      const { setGestureTypes, gestureTypes, quickGestureOptions } = useHeatmapContext();
      const [showCategoryOptions, categoryOptionsToggler] = useState(false);
      const [selectSubOptions, onSelectGestureTypes] = useState([]);
      const [selectMainOptions, onSelectGestureHeaders] = useState([]);
  
      const trackEvents = (gestureOptionsVal, gestoreTypesValues) => {
        dispatch(trackPageViews(null, {
          eventName: 'hm_filter_change',
          track_type: 'event',
          eventProperty: {
            filters: gestureOptionsVal,
            gestures: gestoreTypesValues,
            screenname,
          }
        }))
      }
      const onChangeHeader = (e) => {
        let newMainOpts = [];
        if (selectMainOptions.indexOf(e.target.value) > -1) {
          newMainOpts = selectMainOptions.filter((x) => x !== e.target.value);
          onSelectGestureTypes([]);
          const gestureValues = gestureTypes.filter((el) => subCategories.indexOf(el) < 0);
          setGestureTypes(gestureValues);
          trackEvents(quickGestureOptions, gestureValues);
        } else {
          newMainOpts = [...selectMainOptions, ...[e.target.value]];
          onSelectGestureTypes(subCategories);
          const gtypesCopy = [
            ...gestureTypes.filter((el) => subCategories.indexOf(el) < 0),
            ...subCategories,
          ];
          setGestureTypes(gtypesCopy);
          trackEvents(quickGestureOptions, gtypesCopy)
          if (isEqual(gtypesCopy.sort(), gestureTypesList.sort()))
            allGestureToggler(true);
        }
        onSelectGestureHeaders(newMainOpts);
      };
      const onChangeOptions = (e) => {
        let newOpts = [...selectSubOptions];
        if (newOpts.indexOf(e.target.value) > -1) {
          newOpts = newOpts.filter((x) => x !== e.target.value);
          onSelectGestureHeaders([]);
        } else {
          newOpts = [...selectSubOptions, ...[e.target.value]];
          if (isEqual(newOpts.sort(), subCategories.sort()))
            onSelectGestureHeaders([title]);
        }
        if (gestureTypes.indexOf(e.target.value) > -1) {
          const gestureValues = gestureTypes.filter((el) => el !== e.target.value);
          setGestureTypes(gestureValues);
          trackEvents(quickGestureOptions, gestureValues);
        }else {
          const gtypesCopy = [
            ...gestureTypes.filter((el) => el !== e.target.value),
            ...[e.target.value],
          ];
          setGestureTypes(gtypesCopy);
          trackEvents(quickGestureOptions, gtypesCopy)
          if (isEqual(gtypesCopy.sort(), gestureTypesList.sort()))
            allGestureToggler(true);
        }
        onSelectGestureTypes(newOpts);
      };
      const getSumPercent = useMemo(
        () =>
          subCategoryByTitle?.[0]?.percentage >= 0 &&
            !Number.isNaN(summedPercent(subCategoryByTitle))
            ? summedPercent(subCategoryByTitle)
            : '',
        [subCategoryByTitle]
      );
      const toggler = useCallback(() => {
        categoryOptionsToggler(!showCategoryOptions);
      }, [categoryOptionsToggler, showCategoryOptions]);
      const toggleIcon = useMemo(
        () => (!showCategoryOptions ? <DownOutlined /> : <UpOutlined />),
        [showCategoryOptions]
      );
      useEffect(() => {
        if (isAllGestures) {
          onSelectGestureTypes(subCategories);
          onSelectGestureHeaders(mainCategories);
        }
      }, [isAllGestures]);
      useEffect(() => {
        if (!gestureTypes.length) {
          onSelectGestureTypes([]);
          onSelectGestureHeaders([]);
        }
      }, [gestureTypes, quickGestureOptions]);
      useEffect(() => {
        if (
          quickGestureOptions.length === 1 &&
          quickGestureOptions.indexOf('israge') > -1
        ) {
          onSelectGestureTypes(tapsSet);
          setGestureTypes(tapsSet);
          onSelectGestureHeaders(['Taps']);
        }
      }, [quickGestureOptions]);
      
      return (
        <div className="sub-category-header">
          <span className="category-header">
            <Checkbox
              className="category other-category"
              key={title}
              value={title}
              checked={selectMainOptions.indexOf(title) > -1}
              onChange={onChangeHeader}
            >
              <span className="category-title">{title}</span>
            </Checkbox>
            <Button
              type="text"
              size="small"
              onClick={toggler}
              icon={toggleIcon}
            />
            <span className="down-icon">
              <>{getSumPercent}</>
            </span>
          </span>
          <div
            className={classNames('sub-items', {
              'hide-check-box-group-items': !showCategoryOptions,
            })}
          >
            {subCategoryByTitle?.length > 0 && subCategoryByTitle?.map((v) => (
              <span key={v.name} className="category-header">
                <Checkbox
                  className="category other-category"
                  // disabled={v.percentage === 0}
                  key={v.name}
                  value={v.name}
                  checked={selectSubOptions.indexOf(v.name) > -1}
                  onChange={onChangeOptions}
                >
                  {v.name}
                </Checkbox>
                <span className="down-icon sub-title">
                  {typeof v.percentage !== 'undefined' && (
                    <div className="item-percent">
                      {getPercentageSign(preciseNumber(v.percentage, 2))}
                    </div>
                  )}
                </span>
              </span>
            ))}
          </div>
        </div>
      );
    }
  );

const GesturesTypeSelect = memo(() => {
  const {
    orientation,
    quickGestureOptions,
    gestureTypes,
    setGestureTypes,
    deviceClass,
  } = useHeatmapContext();
  const dispatch = useDispatch();
  const {
    urlReducer: { appId, screenname },
    appFilter: {
      dateSegment,
      heatmap: { segment },
    },
  } = useSelector(({ urlReducer, appFilter }) => ({
    urlReducer,
    appFilter,
  }));

  const deviceClassFilter = useMemo(
    () => [{ attribute: 'device_class', operator: 'in', value: [deviceClass] }],
    [deviceClass]
  );

  const isFirstOrLastGestures = useCallback(
    (attribute) =>
      (attribute === 'is_first_screen' &&
        quickGestureOptions.indexOf('is_first_gesture') <= -1) ||
      (attribute === 'is_last_screen' &&
        quickGestureOptions.indexOf('is_last_gesture') <= -1),
    [quickGestureOptions]
  );

  const quickFormatGestures = useMemo(() => {
    let newQuickParams = [];
    quickGestureOptions.length
      ? quickGestureOptions.map((attribute) => {
        let params = [
          {
            attribute,
            operator: 'equal',
            value: attribute !== 'isresponsive' ? 'True' : 'False',
          },
        ];
        if (isFirstOrLastGestures(attribute)) {
          params = [
            ...params,
            ...[
              {
                attribute:
                  attribute === 'is_first_screen'
                    ? 'is_first_gesture'
                    : 'is_last_gesture',
                operator: 'equal',
                value: 'True',
              },
            ],
          ];
        }
        newQuickParams = [...newQuickParams, ...params];
        return newQuickParams
      })
      : [];
    return newQuickParams;
  }, [isFirstOrLastGestures, quickGestureOptions]);

  const orientationSegment = useMemo(
    () => [
      {
        attribute: 'orientation',
        operator: 'equal',
        value: orientation,
      },
    ],
    [orientation]
  );

  const megaFilters = useMemo(
    () => [
      ...formattedFilters(segment) || [],
      ...deviceClassFilter,
      ...quickFormatGestures,
      ...orientationSegment,
    ],
    [segment, deviceClassFilter, quickFormatGestures, orientationSegment]
  );

  const payload = useMemo(
    () => ({
      appid: appId,
      screen_name: screenname,
      mega_filters: megaFilters,
      date_range: dateSegment,
    }),
    [dateSegment, screenname, megaFilters, appId]
  );

  const {
    data: heatmapGesturesTypeData,
    isLoading,
    isRefetching,
  } = useHeatmapGesturesType(payload);

  const  heatmapGesturesData = useMemo(()=> heatmapGesturesTypeData?.data || [], [heatmapGesturesTypeData] ) 

  const [isAllGestures, allGestureToggler] = useState(true);

  const sumOfGestureCount = useMemo(
    () =>
      !Number.isNaN(summedCount(heatmapGesturesData))
        ? summedCount(heatmapGesturesData)
        : '',
    [heatmapGesturesData]
  );

  const allGestureHandler = useCallback(
    (e) => {
      if (e.target.checked) setGestureTypes([...gestureTypesList]);
      else setGestureTypes([]);
      dispatch(trackPageViews(null, {
        eventName: 'hm_filter_change',
        track_type: 'event',
        eventProperty: {
          filters: quickGestureOptions,
          gestures: e.target.checked ? gestureTypesList : [],
          screenname,
        }
      }))
      allGestureToggler(e.target.checked);
    },
    [setGestureTypes, allGestureToggler]
  );

  useEffect(() => {
    if (!isEqual(gestureTypes.sort(), gestureTypesList.sort()))
      allGestureToggler(false);
  }, [gestureTypes]);

  return (
    <FilterStyled data-intercom-target="Gesture filters">
      <FilterTitleStyled>Gestures</FilterTitleStyled>
      <FilterCascadingSelectStyled>
        <span className="category-header">
          <Checkbox
            className="category main-category"
            checked={isAllGestures}
            value={isAllGestures}
            onChange={allGestureHandler}
          >
            <span className="category-title">All Gestures</span>
          </Checkbox>
          <span className="down-icon">
            {isLoading || isRefetching ? (
              'loading...'
            ) : (
              <Tooltip
                title={ heatmapGesturesData?.length > 0 && heatmapGesturesData?.map(({ count }) => count || 0)
                  .reduce((pV, cV) => pV + cV, 0)}
              >
                {sumOfGestureCount}
              </Tooltip>
            )}
          </span>
        </span>
        {map(gesturesCategory, (value, key) => (
          <CategoryItems
            key={key}
            title={key}
            subCategories={value}
            mainCategories={Object.keys(gesturesCategory)}
            subCategoryByTitle= { heatmapGesturesData?.length && heatmapGesturesData.filter(
              (v) => v.category === key
            )}
            isAllGestures={isAllGestures}
            allGestureToggler={allGestureToggler}
          />
        ))}
      </FilterCascadingSelectStyled>
    </FilterStyled>
  );
});
export default GesturesTypeSelect;
