import React, { useMemo, memo, useCallback } from 'react';
import styled from 'styled-components';
import { useRouter } from 'next/router';
import { useDispatch, useSelector } from 'react-redux';

import { getDate } from 'Utils/DateConversion/dateConversionUtils';
import { compactNotation, convertGetTime, preciseNumber } from 'Utils/helpers/commonUtils';
import CellOverflowTooltip from 'Utils/helpers/CellOverflowTooltip';
import { formatDisplayTime } from 'Utils/constants/index';
import { containsOnlyNumbers } from 'Utils/helpers/numberFormatter';
import { createColumnHelper } from '@tanstack/react-table';
import { Tooltip } from 'antd';
import { trackPageViews } from 'redux/actions/trackingReport';
import IconHeatmap from 'public/static/heatmap-icon.svg'
import { useIsAppType } from 'hooks/useIsAppType';
import Screenshot from '../Screen/Screenshot';
import useRenamedScreenName from './useRenamedScreenName';

  const Cell = styled.div`
  display: flex;
  height: 100%;
  width: 100%;
  justify-content: center;
  align-items: flex-start;
  flex-direction: column;
  flex-wrap: nowrap;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
`;

const Wrapper = styled(Cell)`
  flex-direction: row;
  justify-content: flex-start;
  align-items: center;
  padding-right: 10px;

  > svg{
    margin-right: 10px;
    max-width: 28px;
  }

  .tooltip-wrapper {
    color: #161e35;
    font-size: 12px;
    line-height: 15px;
    overflow-wrap: break-word;
    word-wrap: break-word;
    word-break: break-word;
  }
`;

const EllipseText = styled.div`
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  width: 100%;
`

const WrapperDate = styled.div``;
const StyledSpan = styled.div`
  font-size: 0.8125rem;
  color: #8a99b1;
  margin-top: 5px;
`;

const HeaderSpan = styled.span`
  width: 100%;
`

const ButtonStyled = styled.button`
  height: 30px;
  padding: 0;
  border-color: transparent;
  background-color: transparent;
  cursor: pointer;
`

const ScreenNameRow = memo(({ row }) => {
  const { screenname, screenShotImageUrl } = row.original;
  const { tooltipElement, renamedScreenName } = useRenamedScreenName(screenname);
  const isWebSdk = useIsAppType('web');
  const router = useRouter();
  const { currentAppReducer: { _id: appId } } = useSelector((state) => state);
  const dispatch = useDispatch();

  const handleCreateHeatmap = useCallback(() => {
    const encodedScreenName = encodeURIComponent(screenname);
    dispatch(trackPageViews(null, {
      eventName: 'wa_heatmaps_click_create_heatmap',
      eventProperty: {
        source_feature: 'screens',
      }
    }))
    router.push(
      `/integration?appId=${appId}&parentType=webHeatmaps&screen_name=${encodedScreenName}&reportId=new`,
      `/app/${appId}/web-heatmap/new?screen_name=${encodedScreenName}`
    );
  }, [ screenname, dispatch, router, appId ]);

  if ( isWebSdk ) {
    return (
      <Wrapper data-element="web-screenname">
        <Tooltip title='Create heatmap' placement='bottom'>
          <ButtonStyled onClick={handleCreateHeatmap} type='text' size='small'>
            <IconHeatmap />
          </ButtonStyled>
        </Tooltip>
        <CellOverflowTooltip
          className='tooltip-wrapper web-cell-screenname'
          text={screenname}
          value={renamedScreenName}
          tooltipElement={tooltipElement}
        />
      </Wrapper>
    )
  }

  return (
    <Wrapper>
      <Screenshot imageUrl={screenShotImageUrl} key={screenname} />
      <CellOverflowTooltip
        className='tooltip-wrapper'
        text={screenname}
        value={renamedScreenName}
        tooltipElement={tooltipElement}
      />
    </Wrapper>
  );
});

const TimeRow = ({ value }) => (
  value < 60 ? `${Math.round(value)} sec` : convertGetTime({ durationInSecs: value })
);

const AverageRow = ({ value }) => (
  <span>{`${value !== null ? compactNotation(value, 2) : 0}`}</span>
);

const PercentageRow = ({ value }) => {
  if (value === -1 || value === null) return <>-</>;
  return <span>{`${value > 0 ? preciseNumber(value, 4) : 0.0} %`}</span>;
};

const CountRow = ({ value }) => <>{compactNotation(value, 2)}</>;

const CommonNameRow = ({ value }) => <EllipseText>{containsOnlyNumbers(value)}</EllipseText>;

const ColumnSelection = memo(({ cell, row }) => {

  const {
    column: { id, totalWidth },
  } = cell;
  const value = cell.getValue(id);

  switch (id) {
    case 'screenname':
      return <ScreenNameRow width={totalWidth} row={row} key={id} />;
    case 'avgScreenTimePerVisit':
    case 'avgScreenTimePerUser':
    case 'medianScreenDuration':
      return <TimeRow value={value} />;
    case 'averageGesturesPerVisit':
      return <AverageRow value={value} />;
    case 'quitPercentage':
    case 'openPercentage':
    case 'ragePercentage':
    case 'doupleTapPercentage':
    case 'longPressPercentage':
    case 'singleTapPercentage':
    case 'swipeDownPercentage':
    case 'swipeLeftPercentage':
    case 'swipeRightPercentage':
    case 'swipeUpPercentage':
    case 'zoomInPercentage':
    case 'zoomOutPercentage':
    case 'crashPercentage':
    case 'uiFreezePercentage':
    case 'visitPercentage':
    case 'visitorPercentage':
    case 'avgVisitCountPerUser':
    case 'pageRefreshPercentage':
    case 'bouncePercentage':
    case 'deadClickPercentage':
      return <PercentageRow value={value} />;
    case 'visitorCount':
    case 'visitCount':
    case 'rageGestureCount':
    case 'quitCount':
    case 'gestureCount':
    case 'crashCount':
    case 'uiFreezeCount':
      return <CountRow value={value} />;
    case 'screenFirstVisitedOn':
    case 'screenLastVisitedOn':
      return (
        <WrapperDate>
          {formatDisplayTime(value, 'MMM DD, yyyy')}
          <StyledSpan>{getDate(value, 'EEE hh:mm  a')}</StyledSpan>
        </WrapperDate>
      );
    default:
      return <CommonNameRow value={value} />;
  }
});

export default function useColumns(headers) {
  const columnHelper = createColumnHelper();
  const isWebSDK = useIsAppType('web');

  const getScreenName = (original) => {
    const { displayName, screenname = '' } = original || {};
    if (displayName) return displayName.toLowerCase();
    return screenname.toLowerCase();
  }

  const customSorting = useCallback((firstRow, secondRow) => {
    const firstElement = getScreenName(firstRow?.original);
    const secondElement = getScreenName(secondRow?.original);
    if (firstElement > secondElement) return 1
    if (secondElement > firstElement) return -1
    return 0;
  }, []);

  const columns = useMemo(
    () =>
      headers
        .map((header) => {
          const {
            isVisible,
            attribute,
            title,
            titleInfo: tooltipInfo,
            isSortable,
          } = header;
          return isVisible
            ?
            columnHelper.accessor(attribute, {
              header: <Tooltip title={tooltipInfo}><HeaderSpan>{title}</HeaderSpan></Tooltip>,
              cell: ({ cell, row }) => <ColumnSelection cell={cell} row={row} />,
              // eslint-disable-next-line no-nested-ternary
              size: attribute === 'screenname' ? isWebSDK ? 380 : 250 : 180,
              sortDescFirst: true,
              enableSorting: isSortable,
              sortingFn: attribute === 'screenname' ? customSorting : 'basic',
            })
            : null;
        })
        .filter((el) => el),
    [headers]
  );

  return columns;
}
