import React, { memo, useCallback } from 'react';
import classnames from 'classnames';
import { useDispatch, useSelector } from 'react-redux';
import { Button } from 'antd';
import { useHeatmapContext } from 'components/features/heatmaps/Context/HeatmapContext';
import { trackPageViews } from 'redux/actions/trackingReport';
import { MobileOutlinedStyled } from 'components/features/heatmaps/HeatmapDetails/HeatmapStyled'

const DeviceOritentation = memo(() => {
  const dispatch = useDispatch();
  const { orientation, setOrientation, setHeatmapRegionSelectionEnabled } = useHeatmapContext();
  const { screenname } = useSelector((state) => state.urlReducer);
  const handleClick = useCallback((orientn) => {
    setOrientation(orientn);
    setHeatmapRegionSelectionEnabled(false)
    dispatch(
      trackPageViews(null, {
        eventName: 'hm_change_device_orientation',
        track_type: 'event',
        eventProperty: {
          screenname,
          orientation: orientn === 1 ? 'vertical' : 'horizontal',
        },
      })
    );
  }, [setHeatmapRegionSelectionEnabled]);
  return (
    [1, 0].map((orientn) => (
      <Button
        data-intercom-target={orientn === 1 ? "vertical" : "horizontal"}
        key={orientn}
        className={classnames('heatmap-device-orientation', {
          active: orientation === orientn,
        })}
        icon={<MobileOutlinedStyled orientation={orientn} />}
        type="text"
        onClick={() => handleClick(orientn)}
      />
    ))
  );
});

export default DeviceOritentation;
