import React, { useEffect, memo, useCallback, useMemo } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import Router, { useRouter } from 'next/router';
import styled from 'styled-components';
import { attributeProperties } from 'redux/actions/filter';
import { urlSegmentEncoder } from 'Utils/helpers/urlSegmentEncoder';
import { useRestrictionContext } from 'components/IntegratePages/layout/context/restrictionContext'
import NoFeatureOverlay from 'components/common/NoFeatureOverlay';
import { formattedFilters } from 'Utils/ScreenPageFilter';
import { useIsAppType } from 'hooks/useIsAppType';
import { themeCommon } from 'theme/theme';
import useEventUserProperties from 'hooks/useEventUserProperties';
import some from 'lodash/some';
import { goToPage } from 'components/shared/Pagination';
import { useFeatureFlag } from 'uxcam-frontend-components';
import HeatmapDetails from './HeatmapDetails';
import ScreenPage, { defaultSortBy } from './Screen/index';
import { HeatmapContextProvider } from './Context/HeatmapContext';
import { useAppDeviceClass, useScreenListQuery, useSearchAttribute, useWebScreenListQuery } from './hooks';
import { useScreenNameUrlSuffix } from './hooks/useScreenNameUrlSuffix';
import { ScreenListContextProvider } from './Context/ScreenListContext';
import HeatmapsPageLocked from './HeatmapsPageLocked';
import { screenColumnAttributes } from './constants';
import WebScreenTable from './Screen/WebScreenTable';
import WebScreenAnalytics from './WebScreenAnalytics';

const Wrapper = styled.div`
  position: relative;
  height: ${({ screenName, bottomBarClassFlag }) => (screenName ? `calc(100vh - 68px)` : `calc(100vh - ${bottomBarClassFlag ? '178' : '125'}px)`)};
  margin: ${({ isFilterBarVisible }) => isFilterBarVisible ? '70px 16px 16px' : '60px 16px 16px'};
  padding-top: 16px;
  pointer-events: ${({ isGlobalFilterVisible }) => isGlobalFilterVisible ? `none` : ''};
  tr {
    cursor: ${({ isWebApp }) => (isWebApp ? 'default' : 'pointer')};
    div[data-element="web-screenname"] {
      display: flex;
      align-items: center;
      gap: 14px;
    span{
      font-weight: 600;
    }
    svg{
      min-width: 28px;
      path{
        transition: fill 0.2s ease-in-out;
      }
      path:last-of-type{
        fill: ${themeCommon.color.Sky};
      }
      g path:last-of-type{
        fill: ${themeCommon.color.Midnight}
      }
      /* path:nth-child(5){
        fill: ${themeCommon.color.Midnight};
      } */
  }
}
  &:hover {
    div[data-element="web-screenname"] svg{
      path:nth-last-of-type(2){
      fill: ${themeCommon.color.Primary05}; 
      }
      path:last-of-type{
        fill: ${themeCommon.color.Midnight};
      }
      g path:last-of-type{
        fill: ${themeCommon.color.Sky}
      }
      /* path:nth-child(5){
        fill: ${themeCommon.color.Sky};
      } */
    }
  }
}
`;

// Reverse mapping for converting API values back to frontend attributes
const reverseAttributeMapping = Object.entries(screenColumnAttributes).reduce((acc, [key, value]) => {
  acc[value] = key;
  return acc;
}, {});

const ScreenWrapper = memo(() => {
  const dispatch = useDispatch();
  const isWebApp = useIsAppType('web');
  const {
    urlReducer: {
      screenname,
      appId,
      screenpage = 1,
      selectedTab = 'heatmaps',
      parentType,
      sessionid,
      screenVisitPage,
      starttime,
      screenVisitId
    },
    appFilter: {
      heatmap: { segment = [] },
      dateSegment
    },
    currentOrgReducer: currentOrg,
    commonReducer: { bottomBarClassFlag }
  } = useSelector(({ urlReducer, appFilter, currentOrgReducer, commonReducer }) => ({
    urlReducer,
    appFilter,
    currentOrgReducer,
    commonReducer,
  }));
  const { showScreensPageLockScreen } = useRestrictionContext()

  // Initialize serverSortedOrder from localStorage to persist sorting across date changes
  const [serverSortedOrder, setServerSortedOrder] = React.useState(() => {
    try {
      const storedSort = localStorage.getItem('screenSortBy');
      if (storedSort && storedSort !== 'undefined') {
        return JSON.parse(storedSort);
      }
    } catch (err) {
      // silent fail
    }
    return defaultSortBy;
  });

  const [sortedBy, setSortedBy] = React.useState([]);
  const [searchFilter, setSearchFilterState] = React.useState('');
  const [isServerSideMode, setIsServerSideMode] = React.useState(false);
  const [serverPageIndex, setServerPageIndex] = React.useState(1);
  const router = useRouter()
  const redirectTimeoutRef = React.useRef(null);
  const isWebHeatmapsEnabled = useFeatureFlag('web-heatmaps')

  // Memoize setSearchFilter to prevent infinite loops
  const setSearchFilter = React.useCallback((value) => {
    setSearchFilterState(value);
  }, []);

  // Reset search filter and pagination when date segment or app changes
  React.useEffect(() => {
    setSearchFilterState('');
    setIsServerSideMode(false);
    setServerPageIndex(1);
  }, [dateSegment, appId]);

  const setSortByVal = (newSort) => {
    const { id, desc } = newSort()[0];
    const sortByVal = [{
      id,
      desc,
    }]
    setSortedBy(sortByVal);
  }

  // Save serverSortedOrder to localStorage when it changes
  React.useEffect(() => {
    try {
      localStorage.setItem('screenSortBy', JSON.stringify(serverSortedOrder));
    } catch (err) {
      // silent fail
    }
  }, [serverSortedOrder]);

  const { megaDropdownVisible, megaBottomDropdownVisible, filterBarVisible } = useSelector(
    (state) => state.megaFilterReducer
  )

  const isGlobalFilterVisible = useMemo(() => megaDropdownVisible || megaBottomDropdownVisible, [megaDropdownVisible, megaBottomDropdownVisible])

  const planFeature = currentOrg?.planFeature;
  const { screenAnalysis } = planFeature || {};
  const { screenNameUrlSuffix, replacedScreenName } = useScreenNameUrlSuffix()

  // serverSortedOrder and searchFilter dependencies to trigger api call on server sort/search change
  const reqBody = useMemo(
    () => {
      const baseFilters = formattedFilters(segment) || [];
      // Only add screen_name filter when searchFilter has actual content (not empty/whitespace)
      const filters = searchFilter && searchFilter.trim()
        ? [
          ...baseFilters,
          {
            attribute: 'screen_name',
            operator: 'contains',
            value: searchFilter.trim(),
          },
        ]
        : baseFilters;

      const body = {
        appid: appId,
        date_range: dateSegment,
        filters,
        orderBy: [{
          sortName: screenColumnAttributes[serverSortedOrder[0]?.id || 'visitCount'],
          sortOrder: serverSortedOrder[0]?.desc ? 'desc' : 'asc',
        }],
      };

      // Add page parameter for server-side pagination when we need data beyond current batch
      // Each API call returns 1001 items, covering ~50 pages
      // Initial request (no page): items 1-1001, covers pages 1-50
      // page: 51 request: items 1001-2001, covers pages 51-100
      // page: 101 request: items 2001-3001, covers pages 101-150
      // We need a new fetch at pages 51, 101, 151, etc. (every 50 pages after the first 50)
      const batchSize = 50; // Each batch covers 50 pages (1000 items + 1 overlap)
      const currentBatch = Math.ceil(serverPageIndex / batchSize); // 1-50 = batch 1, 51-100 = batch 2
      const needsServerFetch = isServerSideMode && currentBatch > 1;
      if (needsServerFetch) {
        // Calculate the first page of the current batch
        const batchStartPage = (currentBatch - 1) * batchSize + 1; // batch 2 starts at page 51
        body.page = batchStartPage;
      }

      return body;
    },
    [appId, dateSegment, segment, serverSortedOrder, searchFilter, isServerSideMode, serverPageIndex]
  );

  const { data: screenList, pagination: apiPagination, isLoading, isFetching, lastUpdate, refresh } = useScreenListQuery(reqBody, 'screen-table-list', isWebApp);

  // Detect when we need to enable server-side mode
  // Enable when: data >= 1001 items OR pagination info indicates more pages
  // Once enabled, stays enabled for this app/date combination
  React.useEffect(() => {
    const hasMorePages = apiPagination && apiPagination.pages > 50;
    const hasMaxData = screenList && screenList.length >= 1001;

    if ((hasMorePages || hasMaxData) && !searchFilter) {
      setIsServerSideMode(true);
    }
    // Note: We don't disable server-side mode if the count drops below 1001
    // because that could be due to filters, not because the dataset is actually small
  }, [screenList, searchFilter, apiPagination]);
  let webScreenListReqBody = '';
  try {
    webScreenListReqBody = JSON.parse(
      localStorage.getItem('webScreenListReqBody')
    );
  } catch (err) {
    // silent fail
  }

  const postBody = useMemo(
    () => ({
      appid: appId,
      filters: formattedFilters(segment) || [],
      date_range: dateSegment,
      ...((sortedBy?.length || webScreenListReqBody?.orderBy) && {
        orderBy: sortedBy?.length ? [{
          sortName: screenColumnAttributes[sortedBy[0]?.id] || sortedBy[0]?.id,
          sortOrder: sortedBy[0]?.desc ? 'desc' : 'asc',
        }] : webScreenListReqBody?.orderBy
      }),
      page: Number(screenpage) || 1,
    }), [appId, dateSegment, screenpage, segment, sortedBy, webScreenListReqBody?.orderBy])

  useEffect(() => {
    try {
      localStorage.setItem('webScreenListReqBody', JSON.stringify(postBody));
    } catch (err) {
      // silent fail
    }
  }, [postBody]);

  const { data: webScreenList, refetch: webRefetch, isLoading: isWebLoading, isFetching: isWebFetching } = useWebScreenListQuery(postBody, 'web-screen-table-list', isWebApp);

  const callRedirectPage = useCallback(() => {
    if (!isWebApp) return;
    postBody.page = 1
    webRefetch()

    goToPage({
      page: 1,
      appId,
      segment,
      parentType,
      dateSegment,
    });
  }, [isWebApp, postBody, webRefetch, appId, segment, parentType, dateSegment]);

  useEffect(() => {
    if (sortedBy?.length && sortedBy[0]?.sortName !== '') {
      callRedirectPage();
    }
  }, [sortedBy]);

  useEventUserProperties()

  const payload = useMemo(
    () => ({
      attribute: 'user_custom_property',
      filter: [],
      search: '',
      dropdownLimit: 501,
      date_range: dateSegment,
      appid: appId,
      table: 'session',
    }),
    [appId, dateSegment]
  );

  const onRouteHandler = useCallback(() => {
    const isScreenNamePresent = some(screenList, { 'screenname': screenname });
    if (screenList?.length > 0 && screenname && !isScreenNamePresent) {
      Router.push('/error?errorStatus=404');
    }

    let segmentCopy;
    if (screenname) {
      segmentCopy = [...segment, ...[dateSegment]];
    } else {
      segmentCopy = [...segment];
    }

    const includeScreenSessionUrl = sessionid ? `/${screenVisitPage}/${screenVisitId}/session/${sessionid}/${starttime}` : '';
    const urlSuffix = replacedScreenName ? `details/${screenname}/${selectedTab}${includeScreenSessionUrl}` : `list/${screenpage}`;

    let url = `app/${appId}/screens/${urlSuffix}`;
    const query = `parentType=heatmapsList&appId=${appId}&screenVisitPage=${screenVisitPage}&sessionid=${sessionid}&starttime=${starttime}&screenpage=${screenpage}&screenname=${replacedScreenName}&selectedTab=${selectedTab}`;
    url = urlSegmentEncoder(url, segmentCopy);

    Router.push(`/integration?${query}`, `${url}${screenNameUrlSuffix}`, { shallow: true });

  }, [dateSegment, screenname, selectedTab, screenpage, appId, segment, screenList, screenNameUrlSuffix]);

  const onSuccess = ({ data: { data } }) => {
    dispatch(
      attributeProperties({
        data,
        attribute: 'user_custom_property',
      })
    );
  };

  useEffect(() => {
    if (parentType !== 'heatmapsList') return;
    onRouteHandler();
  }, [segment]);

  // @NOTE: Remove this with feature flag removal

  React.useEffect(() => {
    if (redirectTimeoutRef.current) {
      clearTimeout(redirectTimeoutRef.current);
    }

    if (!isWebHeatmapsEnabled && isWebApp) {
      redirectTimeoutRef.current = setTimeout(() => {
        if (!isWebHeatmapsEnabled && isWebApp) {
          router.push(
            `/integration?parentType=overview&appId=${appId}`,
            `/app/${appId}/overview`
          )
        }
      }, 1500);
    }

    return () => {
      if (redirectTimeoutRef.current) {
        clearTimeout(redirectTimeoutRef.current);
      }
    };
  }, [appId, isWebHeatmapsEnabled, isWebApp, router])

  useSearchAttribute(payload, onSuccess);
  useAppDeviceClass({
    appid: appId,
    mega_filters: formattedFilters(segment) || [],
    date_range: dateSegment,
  });

  const sortByTransform = (sort) => {
    if (sort.length > 0) {
      const { sortName, sortOrder } = sort[0];
      return [{
        id: reverseAttributeMapping[sortName] || sortName,
        desc: sortOrder === 'desc',
      }]
    }
    return []
  }

  if (showScreensPageLockScreen) {
    return <HeatmapsPageLocked />
  }

  return (
    <NoFeatureOverlay isFeatureAvailable={screenAnalysis} page='heatmaps'>
      <Wrapper isWebApp={isWebApp} isGlobalFilterVisible={isGlobalFilterVisible} isFilterBarVisible={filterBarVisible} screenName={screenname} bottomBarClassFlag={bottomBarClassFlag}>
        {screenname ? (
          <HeatmapContextProvider>
            <HeatmapDetails />
          </HeatmapContextProvider>
        ) : (
          <ScreenListContextProvider>
            {
              isWebApp ?
                <>
                  <WebScreenAnalytics />
                  <WebScreenTable
                    webScreenList={webScreenList}
                    isLoading={isWebLoading}
                    isFetching={isWebFetching}
                    sortedBy={sortedBy.length ? sortedBy : sortByTransform(webScreenList?.orderBy || [])}
                    setSortedBy={setSortByVal}
                  />
                </>
                :
                <ScreenPage
                  serverSortedOrder={serverSortedOrder}
                  setServerSortedOrder={setServerSortedOrder}
                  screenData={screenList}
                  isLoading={isLoading}
                  isFetching={isFetching}
                  reqBody={reqBody}
                  lastUpdate={lastUpdate}
                  onRefresh={refresh}
                  setSearchFilter={setSearchFilter}
                  isServerSideMode={isServerSideMode}
                  apiPagination={apiPagination}
                  serverPageIndex={serverPageIndex}
                  setServerPageIndex={setServerPageIndex}
                />
            }
          </ScreenListContextProvider>
        )}
      </Wrapper>
    </NoFeatureOverlay>
  );
});

export default ScreenWrapper;
