/* eslint-disable no-nested-ternary */
import { Button, Skeleton } from "antd";
import React, { memo, useCallback, useMemo } from "react";
import { compactNotation, preciseNumber, removeValuesFromFilters } from "Utils/helpers/commonUtils";
import styled from 'styled-components';
import invert from 'lodash/invert';
import { readableTimeFormatter } from "Utils/DateConversion/dateConversionUtils";
import { useSelector, useDispatch } from "react-redux";

import { gestureTypeMapping } from "components/shared/GlobalFilter/components/utils";
import { urlSegmentEncoder } from "Utils/helpers/urlSegmentEncoder";
import { trackPageViews } from 'redux/actions/trackingReport';
import { CloseButtonIcon, GestureCountIcon, GestureTimeIcon, LinkScreenReplayIcon, RageTapCountIcon, SwipeCountIcon, TapCountIcon, UserCountIcon, ZoomCountIcon } from "../heatmapSvgs";
import { useHeatmapContext } from "../Context/HeatmapContext";

const TooltipWrapper = styled.div`
  font-size: 12px;
  font-weight: 500;
  line-height: 24px;

  .ant-skeleton.ant-skeleton-active .ant-skeleton-content .ant-skeleton-title {
    opacity: 0.4;
    height: 12px;
  }

  .ant-skeleton-content .ant-skeleton-paragraph > li {
    opacity: 0.4;
    height: 12px;
  }
`

const TooltipTitleWrap = styled.div`
  display: inline-flex;
  width: 100%;
  align-items: center;

  .ant-btn {
    margin-left: auto;
  }
`

const TooltipContentWrapper = styled.div`
  display: flex;
  flex-direction: column;
  span {
    display: flex;
    align-items: center;
  }
  svg {
    color: #5d97ff;
    margin-right: 5px;
    width: 15px;
  }
`

export const GestureWrapper = styled.div`
  div {
    display: flex;
    align-items: center;
  }
  margin-left: 20px;
  font-weight: 400;
`

export const ButtonWrapper = styled(Button)`
  width: 100%;
  margin-top: 10px;
  color: #5D97FF;
  background-color: #131E33 !important;
  border: 1px solid #5D97FF !important;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;

  span {
    position: relative;
    top: 2px;
  }

  svg {
    margin-right: 8px;
    position: relative;
    top: 2px;
  }
`

export const CloseButtonWrapepr = styled(Button)`
  background-color: transparent !important;
  border: none !important;
  text-align: right;
  float: right;
`

export const InfoSpanWrapper = styled.span`
  color: rgba(255,255,255, 0.5);
`

const HeatmapTooltipContent = ({ isTooltipMetricLoading, heatmapRegionSelectionEnabled, nearestPointValues, handleCloseTooltip }) => {

  const { nearestPoint } = nearestPointValues || {};
  const dispatch = useDispatch()
  const {
    deviceClass,
    gestureTypes,
    regionCoordinates,
    quickGestureOptions,
  } = useHeatmapContext();

  const { startX, startY, endX, endY } = regionCoordinates || {};

  const {
    appFilter: {
      dateSegment,
      heatmap: { segment: filters = [] },
    },
    urlReducer: { appId, screenname },
    screenRenamedList
  } = useSelector(state => state);
  
  const getPercentageValue = useCallback((count, totalCount) => {
    if (count > 0 && totalCount > 0) {
      if (totalCount - count <= 1) {
        return preciseNumber((count / totalCount) * 100, 5)
      }
      if (totalCount - count <= 100) {
        return preciseNumber((count / totalCount) * 100, 4)
      }
      return preciseNumber((count / totalCount) * 100, 2)
    }
    return 0;
  }, []);

  const tapCount = nearestPoint?.tapCount ?? 0;
  const rageTapCount = nearestPoint?.rageTapCount ?? 0;
  const swipeCount = nearestPoint?.swipeCount ?? 0;
  const zoomCount = nearestPoint?.zoomCount ?? 0;
  const gestureCount = nearestPoint?.value ?? 0;
  const userCount = nearestPoint?.userCount ?? 0;
  const gestureTime = nearestPoint?.gestureTime ?? 0;
  const tapsPercentage = getPercentageValue(tapCount, gestureCount);
  const ragePercentage = getPercentageValue(rageTapCount, gestureCount);
  const swipePercentage = getPercentageValue(swipeCount, gestureCount);
  const zoomPercentage = getPercentageValue(zoomCount, gestureCount);
  
  const gestureTypesFilter = useMemo(() => gestureTypes.length < 10 ? gestureTypes.map((type) => gestureTypeMapping[type]) : [], [gestureTypes]);

  const quickGestureTypes = useMemo(() => {
    const filterResult = [];
    quickGestureOptions.map(item => 
      filterResult.push({
        attribute: item,
        operator: 'equal',
        value: true 
      }))
    return filterResult;
  }, [quickGestureOptions]);

  const gestureFilters = useMemo(() => heatmapRegionSelectionEnabled ? [
    {
      attribute: 'gesture_count_per_screen_visit',
      operator: 'greater_or_equal',
      value: 1,
      filters: [
        ...(gestureTypesFilter.length > 0 ? [{
          "attribute": "gesture_type",
          "operator": "in",
          "value": gestureTypesFilter
        }] : []),
        ...(quickGestureTypes.length > 0 ? quickGestureTypes : []),
        {
          'attribute': 'x_bin',
          "operator": "between",
          "value": {
            "lower": `${Math.abs(startX)}`,
            "upper": `${Math.abs(endX)}`
          }
        },
        {
          'attribute': 'y_bin',
          "operator": "between",
          "value": {
            "lower": `${Math.abs(startY)}`,
            "upper": `${Math.abs(endY)}`
          }
        },
      ]
    },
    {
      attribute: 'device_class',
      operator: 'in',
      value: [deviceClass]
    }
  ] : [], [deviceClass, endX, endY, gestureTypesFilter, heatmapRegionSelectionEnabled, quickGestureTypes, startX, startY]);

  const screenReplayURL = useMemo(
    () => {
      if (!heatmapRegionSelectionEnabled) return '';
      let currentScreenName = screenname;
      if (currentScreenName === 'Quit') currentScreenName = 'Exit';
      const originalScreen =
        invert(screenRenamedList)[currentScreenName] || currentScreenName;

      if (!originalScreen) return '';
      let screenNameWithoutSlash = originalScreen?.includes('/')
        ? originalScreen.split('/').join('')
        : originalScreen;
      screenNameWithoutSlash = screenNameWithoutSlash.includes(' ')
        ? screenNameWithoutSlash.split('/').join('')
        : originalScreen;
      const dateSegmentCopy = { ...dateSegment };
      let url = `${process.env.REDIRECT_URL
        }/app/${appId}/screens/details/${encodeURIComponent(
          screenNameWithoutSlash
        )}/screenvisits?`;
      url = urlSegmentEncoder(url, [dateSegmentCopy, ...filters, ...gestureFilters]);
      url = `${url}&screenname=${encodeURIComponent(originalScreen)}`;
      return url;
    },
    [appId, dateSegment, filters, gestureFilters, heatmapRegionSelectionEnabled, screenRenamedList, screenname]
  );

  const handleScreenReplaysClick = () => {
    const dateSegmentCopy = { ...dateSegment };
    const filterApplied =[dateSegmentCopy, ...filters, ...gestureFilters];
    dispatch(
      trackPageViews(null, {
        eventName: 'hm_see_screen_replays',
        track_type: 'event',
        eventProperty: {
          screen_name: `${screenname}`,
          filter_applied: removeValuesFromFilters(filterApplied),
        },
      })
    );
  }

  return (
    <TooltipWrapper>
      {heatmapRegionSelectionEnabled ? <TooltipTitleWrap>
        Metrics inside this area
        <CloseButtonWrapepr icon={<CloseButtonIcon />} onClick={() => handleCloseTooltip()} />
      </TooltipTitleWrap> : null}
      {isTooltipMetricLoading ?
        <Skeleton
          active
          paragraph={{
            rows: 6,
          }}
        /> :
        <>
          <TooltipContentWrapper>
            <span>
              <GestureCountIcon />
              {compactNotation(gestureCount)} gesture{(gestureCount === 0 || gestureCount > 1) ? 's' : ''}
            </span>
            <GestureWrapper>
              <span>
                <TapCountIcon />
                {compactNotation(tapCount)} tap{(tapCount === 0 || tapCount > 1) ? 's' : ''} ({tapsPercentage}%)
              </span>
              <span>
                <RageTapCountIcon />
                {compactNotation(rageTapCount)} rage tap{(rageTapCount === 0 || rageTapCount > 1) ? 's' : ''} ({ragePercentage}%)
              </span>
              <span>
                <SwipeCountIcon />
                {compactNotation(swipeCount)} swipe{(swipeCount === 0 || swipeCount > 1) ? 's' : ''} ({swipePercentage}%)
              </span>
              <span>
                <ZoomCountIcon />
                {compactNotation(zoomCount)} zoom{(zoomCount === 0 || zoomCount > 1) ? 's' : ''} ({zoomPercentage}%)
              </span>
            </GestureWrapper>
            <span>
              <UserCountIcon />
              {compactNotation(userCount)} user{(userCount === 0 || userCount > 1) ? 's' : ''}
            </span>
            <span>
              <GestureTimeIcon />
              {readableTimeFormatter(gestureTime)} on screen until gesture
            </span>
          </TooltipContentWrapper>
          {heatmapRegionSelectionEnabled ?
            <ButtonWrapper onClick={()=> handleScreenReplaysClick()} icon={<LinkScreenReplayIcon />} href={screenReplayURL} target="_blank" rel="noreferrer">{'  '} See screen replays </ButtonWrapper>
            : <InfoSpanWrapper>Click and drag to select an area</InfoSpanWrapper>}
        </>}
    </TooltipWrapper>
  )
}

export default memo(HeatmapTooltipContent);