import React, { useState, memo, useEffect, useCallback } from 'react'
import { SearchOutlined } from "@ant-design/icons";
import { Input } from "antd";
import { useAsyncDebounce } from "react-table";
import styled from "styled-components";

const InputWrap = styled(Input)`
  width: 300px;
  background: #FFFFFF;
  border: 1px solid #C0CAD9;
  border-radius: 4px;
`

const ScreenFilter = memo(({
  globalFilter,
  setGlobalFilter,
  isServerSideSearch = false,
}) => {
  const [value, setValue] = useState('')

  // Increase debounce time for server-side search to reduce API calls
  const debounceTime = isServerSideSearch ? 1000 : 700;

  const handleGlobalText = useAsyncDebounce(text => {
    setGlobalFilter(text.trim() || undefined)
  }, debounceTime)

  const onChangeHandler = useCallback((e) => {
    const searchText = e.target.value;
    setValue(searchText);
    handleGlobalText(searchText);
  }, [handleGlobalText]);

  useEffect(() => {
    setValue(globalFilter)
  }, [globalFilter])

  return (
      <InputWrap
        value={value || ""}
        onChange={onChangeHandler}
        placeholder="Search screens" prefix={<SearchOutlined />}
        autoFocus
      />
  )
})

export default ScreenFilter;
