import React, { memo, useCallback, useState, useEffect } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { Tooltip, Select } from 'antd';
import { fetchPlanHatApi } from 'redux/actions/common';
import { trackPageViews } from 'redux/actions/trackingReport';
import { useHeatmapContext } from 'components/features/heatmaps/Context/HeatmapContext';
import { compactNotation, getPopupContainer } from 'Utils/helpers/commonUtils';
import { DeviceClassSelectStyled } from 'components/features/heatmaps/HeatmapDetails/HeatmapStyled';

const { Option } = Select;
const DeviceClassSelect = memo(() => {
  const dispatch = useDispatch();
  const {
    setDeviceClass,
    deviceClass,
    deviceClassOption,
  } = useHeatmapContext();
  const { screenname } = useSelector((state) => state.urlReducer);
  const [visible, onDropdownVisibleChange] = useState(false)
  const trackEvents = useCallback((dvtype) => {
    dispatch(fetchPlanHatApi({ action: 'Changed device on heatmap page' }));
    dispatch(
      trackPageViews(null, {
        eventName: 'hm_change_device_type',
        track_type: 'event',
        eventProperty: {
          screenname,
          'device type': dvtype,
        },
      })
    );
  }, [screenname]);

  const onSelectHeatmapDevice = useCallback(
    (value) => {
      setDeviceClass(value);
      trackEvents(value);
    },
    [setDeviceClass, trackEvents]
  );

  useEffect(() => {
    if (
      deviceClassOption?.length &&
      deviceClassOption.findIndex((el) => el.deviceclass === deviceClass) <= -1
    ) {
      // onDropdownVisibleChange(true);
      setDeviceClass(deviceClassOption[0].deviceclass)
    }
  }, [deviceClass, deviceClassOption, screenname])
  return (
    <DeviceClassSelectStyled
      size="middle"
      value={deviceClass}
      notFoundContent={null}
      onChange={onSelectHeatmapDevice}
      dropdownClassName="heatmap-deviceclass-drop"
      getPopupContainer={getPopupContainer}
      onDropdownVisibleChange={onDropdownVisibleChange}
      visible={visible}
      open={visible}
      data-intercom-target="Select"
    >
      {deviceClassOption?.map(({ deviceclass: dvClass, gestures }) => (
        <Option value={dvClass} key={dvClass} title={dvClass}>
          <Tooltip title={dvClass.length > 15 ? dvClass : undefined}>
            <span className="screen-filter-title">{dvClass}</span>
          </Tooltip>
          <Tooltip title={`Gesture Count: ${gestures}`}>
            <span className="screen-filter-count">
              {/* <img
                alt=""
                src="/static/stat-icons/icon-gesture.svg"
                className='icon-gesture-image'
              />{' '} */}
              <span className="visit-count">
                {compactNotation(gestures, 2)}
              </span>
            </span>
          </Tooltip>
        </Option>
      ))}
    </DeviceClassSelectStyled>
  );
});
export default DeviceClassSelect;
