import React, { useState, useEffect } from 'react';
import { Popover } from 'antd';
import styled from 'styled-components';
import { useScreenListContext } from 'components/features/heatmaps/Context/ScreenListContext';
import ProgressiveImage from './ProgressiveImage';

export const NO_SCREEN_URL =
  'https://s3.amazonaws.com/static.uxcam.com/staticscreenshots/screen-404.png';

const ImageWrap = styled.img`
  max-width: 20px;
  border: 1px solid #f5f5f5;
`;
const StyledWrapper = styled.div`
  margin-right: 10px;
`;

const Screenshot = ({ imageUrl }) => {
  const { screensImageLoader } = useScreenListContext()
  const [imgSrc, setImgSrc] = useState(NO_SCREEN_URL);
  const loading = imgSrc === NO_SCREEN_URL;
  const loadingContent = screensImageLoader ? 'loading image...' : <ImageWrap src={NO_SCREEN_URL} alt="" />;
  useEffect(() => {
    if (!imageUrl) return;
    const img = new Image();
    img.src = imageUrl;
    img.onload = () => {
      setImgSrc(imageUrl);
    };
  }, [imageUrl]);
  return (
    <StyledWrapper>
      <Popover
        placement="right"
        overlayClassName="screenname-pop-over"
        content={ !loading ? <ImageWrap src={imgSrc} alt="" /> : loadingContent }
      >
        <ProgressiveImage src={imgSrc} alt="" width={25} loading={screensImageLoader} />
      </Popover>
    </StyledWrapper>
  );
};
export default Screenshot;
