import React, { memo } from 'react'
import { useDispatch } from 'react-redux'

import { statBoxMapper } from 'components/features/issues/variables'
import useScreenGraphAPI from 'components/features/heatmaps/hooks/useScreenGraphAPI'
import GraphContainer from 'components/features/issues/IssueDashboard/GraphContainer'
import StatsContainer from 'components/features/issues/IssueDashboard/StatsContainer'

import { trackPageViews } from 'redux/actions/trackingReport'
import { AnalyticsWrapper } from './styles'

import { useScreenBoxAPI } from '../hooks/useScreenBoxAPI'

export type TScreenTimeType = 'averageTime' | 'medianTime';

const WebScreenAnalytics = () => {

    const dispatch = useDispatch();

    const [screenTimeType, setScreenTimeType] = React.useState<TScreenTimeType>('averageTime');

    const {
        screenGraph: graphOptions,
        isGraphLoading,
        selectedStat,
        selectedGraphType,
        setSelectedStat,
        setSelectedGraphType,
    } = useScreenGraphAPI(screenTimeType);

    const {
        boxData,
        isLoading,
        dateString
    } = useScreenBoxAPI(screenTimeType);

    const didMount = React.useRef(false);

    const debounceTimeout = React.useRef<ReturnType<typeof setTimeout> | null>(null);

    React.useEffect(() => {
        if (!didMount.current) {
            didMount.current = true;
            return;
        }
        if (debounceTimeout.current) {
            clearTimeout(debounceTimeout.current);
        }
        debounceTimeout.current = setTimeout(() => {
            dispatch(trackPageViews(null, {
                eventName: 'wa_screens_chartcard_click',
                track_type: 'event',
                eventProperty: {
                    card_name: selectedStat,
                    chart: selectedGraphType,
                    metric: selectedStat === 'screen_time' ? screenTimeType : undefined,
                },
            }));
        }, 200); // 200ms debounce, adjust as needed

        // Fix: Remove return value from useEffect arrow function as per lint error
    }, [selectedStat, selectedGraphType, screenTimeType, dispatch]);

    const handleSetSelectedStat = React.useCallback((stat: string) => {
        setSelectedStat(stat);
    }, [setSelectedStat]);

    const handleSetSelectedGraphType = React.useCallback((type: string) => {
        setSelectedGraphType(type);
    }, [setSelectedGraphType]);

    const handleSetScreenTimeType = React.useCallback((type: TScreenTimeType) => {
        setScreenTimeType(type);
    }, [setScreenTimeType]);

    return (
        <AnalyticsWrapper>
            <div className='analysis-body'>
                <StatsContainer
                    selectedStat={selectedStat}
                    setSelectedStat={handleSetSelectedStat}
                    boxData={boxData}
                    isLoading={isLoading}
                    dateString={dateString}
                    screenTimeType={screenTimeType}
                    setScreenTimeType={handleSetScreenTimeType}
                />
                <GraphContainer
                    title={statBoxMapper[selectedStat as keyof typeof statBoxMapper]}
                    graphData={graphOptions}
                    loading={isGraphLoading}
                    selectedGraphType={selectedGraphType}
                    screenTimeType={screenTimeType}
                    selectedStat={selectedStat}
                    handleChangeGraphType={handleSetSelectedGraphType}
                />
            </div>
        </AnalyticsWrapper>
    )
}

export default memo(WebScreenAnalytics)