import React, { memo, useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { useSelector, useDispatch } from 'react-redux';
import { DashboardTable, StylesProvider } from 'uxcam-frontend-components';
import { differenceBy, isEqual } from 'lodash';
import { OnChangeFn, SortingState } from '@tanstack/react-table';

import { usePagination } from 'components/features/issues/components/ReactTable/usePagination';
import ExportScreenCSV from 'components/shared/ExportCSV/Download';

import { IReduxState } from 'types/reduxStateTypes';

import useLocalStorage from 'hooks/useLocalStorage';
import { trackPageViews } from 'redux/actions/trackingReport';
import useColumns from '../hooks/useColumns';
import ColumnUpdate from './ColumnUpdate';

import defaultHeaders from './mock/webScreenHeaders.json'

import { ToolbarLeft, ToolbarRight, ToolbarWrapper } from './styles';

import { useScreenTableHelper } from './utils';

interface WebScreenList {
    screenname: string;
    visitCount: number;
    visitorCount: number;
    rageGestureCount: number;
    gestureCount: number;
    quitCount: number;
    openCount: number;
    avgScreenTimePerUser: number;
    avgVisitCountPerUser: number;
    avgScreenTimePerVisit: number;
    averageGesturesPerVisit: number;
    quitPercentage: number;
    openPercentage: number;
    ragePercentage: number;
    singleTapPercentage: number;
    doupleTapPercentage: number;
    swipeUpPercentage: number;
    swipeDownPercentage: number;
    screenFirstVisitedOn: Date;
    screenLastVisitedOn: Date;
    displayName: string | null;
    medianScreenDuration: number;
    deadClickCount: number;
    deadClickPercentage: number;
    pageRefreshCount: number;
    pageRefreshPercentage: number;
    visitPercentage: number;
    visitorPercentage: number;
    bouncePercentage: number;

}

interface WebScreenPageProps {
    webScreenList: {
        data: WebScreenList[];
        orderBy: {
            sortName: string;
            sortOrder: string;
        }[]
        pagination: {
            current: number;
            next: number;
            pages: number;
            limit: number;
            total: number;
        }
    }
    isLoading: boolean;
    isFetching: boolean;
    sortedBy: never[];
    setSortedBy: OnChangeFn<SortingState>
}

const updatingHeaders = ['avgScreenTimePerVisit', 'avgScreenTimePerUser'];

const WebScreenTable: React.FC<WebScreenPageProps> = ({
    webScreenList,
    isLoading,
    isFetching,
    sortedBy,
    setSortedBy
}) => {
    const {
        urlReducer: { screenpage },
    } = useSelector<IReduxState, IReduxState>((state) => state)

    const screenPageNumber = useMemo(() => Number(screenpage || 1), [screenpage]);
    const [cachedHeadersData, setCachedHeadersData] = useLocalStorage('webScreenHeaders', defaultHeaders);
    const [defaultCachedHeaders] = useLocalStorage('defaultWebScreenHeaders', defaultHeaders);

    const { pagination, setPagination } = usePagination();
    const prevPaginationRef = useRef<{ current: number; next: number; pages: number; limit: number; total: number } | undefined>(undefined);

    const newPagination = useMemo(
        () => (webScreenList?.pagination ? webScreenList?.pagination : prevPaginationRef?.current),
        [webScreenList?.pagination]
    );

    useEffect(() => {
        if (newPagination) {
            prevPaginationRef.current = newPagination;
        }
    }, [newPagination]);

    useEffect(() => {
        setPagination({ ...pagination, pageIndex: screenPageNumber });
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [screenpage])

    const tableHeaders = useMemo(() => {
        if (isEqual(defaultHeaders, defaultCachedHeaders)) {
            return cachedHeadersData;
        }
        const newHeaders = differenceBy(defaultHeaders, cachedHeadersData, 'attribute') as { attribute: string; title: string; titleInfo?: string }[];
        if (newHeaders.length > 0) {
            return [...cachedHeadersData, ...newHeaders];
        }
        const updatedHeaders = differenceBy(defaultHeaders, cachedHeadersData, 'title') as { attribute: string; title: string; titleInfo?: string }[];
        if (updatedHeaders.length > 0) {
            const tempCachedheaders = cachedHeadersData.map((item: { attribute: string; title: string; titleInfo?: string }) => {
                if (updatingHeaders.includes(item.attribute)) {
                    const updatedItem = defaultHeaders.find(updatedItems => updatedItems.attribute === item.attribute);
                    return {
                        ...item,
                        title: updatedItem?.title || item.title,
                        titleInfo: updatedItem?.titleInfo || item.titleInfo
                    };
                }
                return item;
            });
            return tempCachedheaders;
        }
        return defaultHeaders as { attribute: string; title: string; titleInfo?: string }[];

    }, [cachedHeadersData, defaultCachedHeaders]);

    const screenHeaders = useMemo(() => {
        if (tableHeaders.some((item: { attribute: string; title: string; titleInfo?: string }) => item.attribute === 'displayName')) {
            return tableHeaders;
        }
        return [...tableHeaders]
    }, [tableHeaders]);

    const [headers, setHeaders] = useState(screenHeaders);
    const { handlePagination } = useScreenTableHelper();

    const columns = useColumns(headers);

    useEffect(() => {
        setCachedHeadersData(screenHeaders);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [setCachedHeadersData])

    const rowsData = useMemo(
        () => webScreenList?.data?.map((item) => ({
            ...item,
        })),
        [webScreenList?.data]
    );

    const updateScreenHeaders = useCallback((updatedHeaders: { attribute: string; title: string; titleInfo?: string }[]) => {
        setHeaders(updatedHeaders);
    }, []);

    const dispatch = useDispatch();

    const instrumentedSetSortedBy = useCallback((updaterOrValue: any) => {
        setSortedBy(updaterOrValue);
        let sortName = '';
        let sortOrder = '';
        if (typeof updaterOrValue === 'function') {
            const result = updaterOrValue(sortedBy);
            sortName = result?.[0]?.id || '';
            sortOrder = result?.[0]?.desc ? 'desc' : 'asc';
        } else if (Array.isArray(updaterOrValue)) {
            sortName = updaterOrValue?.[0]?.id || '';
            sortOrder = updaterOrValue?.[0]?.desc ? 'desc' : 'asc';
        }
        if (sortName) {
            dispatch(trackPageViews(null, {
                eventName: 'wa_column_sort',
                track_type: 'event',
                eventProperty: {
                    column_name: sortName,
                    sort: sortOrder,
                },
            }));
        }
    }, [dispatch, setSortedBy, sortedBy]);

    return (
        <>
            <ToolbarWrapper>
                <ToolbarLeft />
                <ToolbarRight
                    data-intercom-target="Filter screens"
                >
                    <ColumnUpdate updateScreenHeaders={updateScreenHeaders} defaultHeaders={defaultHeaders} />
                    <ExportScreenCSV globalFilter={undefined} />
                </ToolbarRight>
            </ToolbarWrapper>
            <StylesProvider>
                <DashboardTable
                    data={rowsData}
                    columns={columns}
                    sorting={sortedBy}
                    setSorting={instrumentedSetSortedBy}
                    resizeMode="onChange"
                    isLoading={isLoading || isFetching}
                    pagination={{
                        ...pagination,
                        totalPagination: webScreenList?.pagination?.pages || 1,
                    }}
                    setPagination={setPagination}
                    handleRouteUpdate={handlePagination}
                    stickyHeaders={['screenname']}
                    tableHeight='100%'
                    tableWidth='100%'
                    emptyText={{ message: 'No screens match the current filters.' }}
                />
            </StylesProvider>
        </>
    );
};

export default memo(WebScreenTable)