import React, { useState, createContext, useContext, useMemo } from 'react';
import { gestureTypesList } from '../constants';

const HeatmapContext = createContext({
  imageOpacity: 50,
  setImageOpacity: () => null,
  orientation: 1,
  setOrientation: () => null,
  quickGestureOptions: [],
  setQuickGestureOptions: () => null,
  heatmapOpacity: 50,
  setHeatmapOpacity: () => null,
  gestureTypes: [],
  setGestureTypes: () => null,
  heatmapRadius: 50,
  setHeatmapRadius: () => null,
  deviceClass: '',
  setDeviceClass: () => null,
  heatmapMax: null,
  setHeatmapMax: () => null,
  heatmapMaxValue: null,
  setHeatmapMaxValue: () => null,
  deviceClassOption: null,
  setDeviceClassOption: () => null,
  heatmapRegionSelectionEnabled: null,
  setHeatmapRegionSelectionEnabled: () => null,
});

const HeatmapContextProvider = ({ children }) => {
  const [orientation, setOrientation] = useState(1);
  const [quickGestureOptions, setQuickGestureOptions] = useState([]);
  const [heatmapOpacity, setHeatmapOpacity] = useState(50);
  const [gestureTypes, setGestureTypes] = useState(gestureTypesList);
  const [heatmapRadius, setHeatmapRadius] = useState(50);
  const [deviceClass, setDeviceClass] = useState('');
  const [heatmapMax, setHeatmapMax] = useState(null)
  const [heatmapMaxValue, setHeatmapMaxValue] = useState(null)
  const [deviceClassOption, setDeviceClassOption] = useState(null)
  const [imageOpacity, setImageOpacity] = useState(50)
  const [heatmapRegionSelectionEnabled, setHeatmapRegionSelectionEnabled] = useState(false);
  const [regionCoordinates, setRegoinCoordinates] = useState(null);
  
  const value = useMemo(
    () => ({
      orientation,
      setOrientation,
      quickGestureOptions,
      setQuickGestureOptions,
      heatmapOpacity,
      setHeatmapOpacity,
      gestureTypes,
      setGestureTypes,
      heatmapRadius,
      setHeatmapRadius,
      deviceClass,
      setDeviceClass,
      heatmapMax,
      setHeatmapMax,
      heatmapMaxValue,
      setHeatmapMaxValue,
      deviceClassOption,
      setDeviceClassOption,
      imageOpacity,
      setImageOpacity,
      heatmapRegionSelectionEnabled,
      setHeatmapRegionSelectionEnabled,
      regionCoordinates,
      setRegoinCoordinates
    }),
    [
      orientation,
      setOrientation,
      quickGestureOptions,
      setQuickGestureOptions,
      heatmapOpacity,
      setHeatmapOpacity,
      gestureTypes,
      setGestureTypes,
      heatmapRadius,
      setHeatmapRadius,
      deviceClass,
      setDeviceClass,
      heatmapMax,
      setHeatmapMax,
      heatmapMaxValue,
      setHeatmapMaxValue,
      deviceClassOption,
      setDeviceClassOption,
      imageOpacity,
      setImageOpacity,
      heatmapRegionSelectionEnabled,
      setHeatmapRegionSelectionEnabled,
      regionCoordinates,
      setRegoinCoordinates
    ]
  );
  return (
    <HeatmapContext.Provider value={value}>{children}</HeatmapContext.Provider>
  );
};

const useHeatmapContext = () => useContext(HeatmapContext);

export {
  HeatmapContextProvider,
  useHeatmapContext,
};
