import React, { useCallback, useMemo } from 'react';
import { Tabs } from 'antd';
import { useDispatch, useSelector } from 'react-redux';
import Router from 'next/router';
import { trackPageViews } from 'redux/actions/trackingReport';
import dynamic from 'next/dynamic';
import ReactLoader from 'components/common/reactLoading';
import { urlSegmentEncoder } from 'Utils/helpers/urlSegmentEncoder';
import { HeatmapsGesturesStyled } from '../HeatmapStyled';
import HeatmapPlots from './HeatmapPlots';
import { useScreenNameUrlSuffix } from '../../hooks/useScreenNameUrlSuffix';
import { encodeSpecialCharsInScreenName } from '../../utils';

const ScreenVisitTable = dynamic(import('./ScreenVIsit/ScreenVisitTable'), {
  loading: () => <ReactLoader />
})

const heatmapsTabMap = {
  Heatmaps: <HeatmapPlots key="heatmaps-plot" />,
  'Screen visits': <ScreenVisitTable key="relevant-sessions" />,
};
const { TabPane } = Tabs;
const HeatmapScreen = () => {

  const dispatch = useDispatch()
  const {
    urlReducer: {
      appId,
      selectedTab = 'heatmaps',
    },
    heatmap: { segment: filters  = [] },
  } = useSelector((state) => ({
    urlReducer: state.urlReducer,
    heatmap: state.appFilter.heatmap,
  }));

  const { replacedScreenName } = useScreenNameUrlSuffix();

  const heatmapsTabV2 = useMemo(() => {
    const tabs = [{ title: 'Heatmaps', key: 'heatmaps' }];
    tabs.push({ title: 'Screen visits', key: 'screenvisits' });
    return tabs;
  }, []);

  const onTabChangeHandler = useCallback((key) => {
    key === 'screenvisits' && dispatch(trackPageViews(null, {
      eventName: 'hm_navigate_to_screenvisit',
      track_type: 'event',
      eventProperty: {
        replacedScreenName,
      },
    }))
    
    const screenUpdated = encodeSpecialCharsInScreenName(replacedScreenName);
    let url = `/app/${appId}/screens/details/${screenUpdated}/${key}`;
    const query = `/integration?parentType=heatmapsList&appId=${appId}&screenname=${screenUpdated}&selectedTab=${key}`;
    url = urlSegmentEncoder(url, filters)
    
    Router.push(query, url);
  }, [appId, dispatch, filters, replacedScreenName]);

  const renderTabComponent = useMemo(
    () =>
      heatmapsTabV2.map(({ title, key }) => (
        <TabPane className="heatmaps-tabs-content" key={key} tab={
          <span data-intercom-target={`Tab ${title}`}>
            {title} 
          </span>
        }>
          {heatmapsTabMap[title]}
        </TabPane>
      )),
    [heatmapsTabV2]
  );

  return (
    <HeatmapsGesturesStyled>
      <Tabs
        animated
        activeKey={selectedTab}
        className="heatmaps-tabs-nav"
        type="card"
        size="large"
        onChange={onTabChangeHandler}
      >
        {renderTabComponent}
      </Tabs>
    </HeatmapsGesturesStyled>
  );
}

export default HeatmapScreen;
