import React, { useState, useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { Form, Input, Button, message } from 'antd';
import { customScreenName } from 'redux/actions/screenFilter';
import { fetchPlanHatApi } from 'redux/actions/common';
import { useQueryClient } from 'react-query';
import { useRenamedScreenOptions } from 'components/features/setting/AppSetting/NewRecordingSection/utils';
import { ScreenRenameInpuStyled } from './HeatmapStyled';

const FormItem = Form.Item;
const htmlInputRegex = /<\/?[a-z][\s\S]*>/i;
const ScreenRenameInput = ({ editScreenName }) => {
  const queryClient = useQueryClient();
  const [form] = Form.useForm();
  const [loadEditScreen, setLoader] = useState(false);
  const [, forceUpdate] = useState({});
  const { urlReducer: urlQuery, screenRenamedList: renamedList } = useSelector(
    ({ urlReducer, screenRenamedList }) => ({
      urlReducer,
      screenRenamedList,
    })
  );
  const dispatch = useDispatch();
  const { getRenamedScreenName } = useRenamedScreenOptions();
  const handleSaveScreenName = async () => {
    try {
      const values = await form.validateFields();
      setLoader(true);
      const { appId: appid,  screenname: screenName } = urlQuery;
      const payload = { appid, screenName, displayName: values.editedScreenName.trim() };
      const res = await dispatch(customScreenName(payload));
      if (res.status && res.status === 422) {
        if (res.data.error && res.data.error.displayName) {
          message.error(res.data.error.displayName[0]);
        } else {
          res.data.error.message
            ? message.error(res.data.error.message)
            : message.error('Oops! Not saved.');
        }
        setLoader(false);
      } else {
        dispatch(
          fetchPlanHatApi({ action: 'Changed screen name on heatmap page' })
        );
        editScreenName(false);
        setLoader(false);
        queryClient.invalidateQueries('screen-table-list');
      }
    } catch (err) {
      /* */
    }
  };
  const handleScreenNameExists = (rule, value, callback) => {
    const errors = [];
    const isValidInput = !htmlInputRegex.test(value);
    if (!isValidInput) {
      errors.push(new Error('Field does not accept HTML tags'));
    }
    if (renamedList[urlQuery.screenname] === value.trim()) {
      errors.push(new Error('Screen name already exists.'));
    }
    callback(errors);
  };
  useEffect(() => {
    forceUpdate({});
  }, []);
  return (
    <ScreenRenameInpuStyled>
      <Form layout="inline" form={form} onFinish={handleSaveScreenName}>
        <FormItem
          name="editedScreenName"
          rules={[
            { required: true, message: 'Screen name is required' },
            {
              max: 50,
              message: 'Field does not accept more than 50 characters',
            },
            {
              whitespace: true,
              message: 'Field does not accept white space only',
            },
            // { pattern: new RegExp(/^[a-zA-Z][a-zA-Z0-9\.\_\-\s\[\]]+$/m), message: 'Only alphabets, numbers, dot, [, ] and underscore allowed in Screen name'},
            { validator: handleScreenNameExists },
          ]}
          initialValue={renamedList && renamedList[urlQuery.screenname] || getRenamedScreenName(urlQuery.screenname)}
        >
          <Input type="text" placeholder="Enter screen name" autoFocus />
        </FormItem>
        <FormItem shouldUpdate>
          {() => (
            <Button
              size="small"
              type="primary"
              htmlType="submit"
              loading={loadEditScreen}
              disabled={
                !form.isFieldsTouched(true) ||
                !!form.getFieldsError().filter(({ errors }) => errors.length)
                  .length ||
                loadEditScreen
              }
            >
              Save
            </Button>
          )}
        </FormItem>
        <Button
          size="small"
          onClick={() => editScreenName(false)}
          disabled={loadEditScreen}
          className="rename-edit-cancel-button"
        >
          Cancel
        </Button>
      </Form>
    </ScreenRenameInpuStyled>
  );
};
export default ScreenRenameInput;
