import React, { memo, useCallback, useState, useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { Button, Row, Col } from 'antd';
import Router from 'next/router';
import dynamic from 'next/dynamic'
import { EditOutlined, LeftOutlined } from '@ant-design/icons';

import { fetchPlanHatApi } from 'redux/actions/common';
import ScreenTooltip from 'components/common/ScreenTooltip';
import { trackPageViews } from 'redux/actions/trackingReport';
import ReactLoader from 'components/common/reactLoading';
import { HeatmapStyled } from './HeatmapStyled';
import HeatmapsScreen from './HeatmapsScreen';
import ScreenRenameInput from './ScreenRenameInput';

const HeatmapsScreenStatistics = dynamic(import('./ScreenStatistics'), {
  loading: () => <ReactLoader />
})

const HeatmapDetails = memo(() => {
  const dispatch = useDispatch();
  useEffect(() => {
    dispatch(fetchPlanHatApi({ action: 'Go to heatmap tab' }));
  }, [dispatch]);
  return (
    <HeatmapStyled>
      <Row gutter={8} className='heatmap-styled-row'>
        <Col span={5}>
          <div className="heatmaps-left-section">
            <BackButton />
            <ScreenTitle />
            <HeatmapsScreenStatistics />
          </div>
        </Col>
        <Col span={19} style={{overflow: 'hidden'}}>
          <div className="heatmaps-right-section">
            <HeatmapsScreen />
          </div>
        </Col>
      </Row>
    </HeatmapStyled>
  );
});
const ScreenTitle = memo(() => {
  const {
    urlReducer: { screenname },
  } = useSelector(({ urlReducer }) => ({ urlReducer }));
  const [isRenameScreen, renameScreenToggler] = useState(false);
  const onRenderScreen = (renderScreen) => <strong className="heatmaps-screen-name">{renderScreen}</strong>
  return (
    <div className="heatmaps-name">
      {isRenameScreen ? (
        <ScreenRenameInput editScreenName={renameScreenToggler} />
      ) : (
        <ScreenTooltip
          originalScreenName={screenname}
          onRenderScreen={onRenderScreen}
        />
      )}
      {!isRenameScreen && (
        <div className="heatmaps-screen-name-edit" data-intercom-target="Edit button">
          <Button
            onClick={() => renameScreenToggler(true)}
            type="text"
            icon={<EditOutlined />}
          />
        </div>
      )}
    </div>
  );
});
const BackButton = memo(() => {
  const dispatch = useDispatch();
  const {
    urlReducer: { appId, screenpage, index: indexCopy, screenname },
  } = useSelector(({ urlReducer }) => ({ urlReducer }));
  const clickHandler = useCallback(
    () => {
      dispatch(trackPageViews(null, {
        eventName: 'hm_close_heatmap_view',
        track_type: 'event',
        eventProperty: {
          screenname
        },
      })
      )
      Router.push(
        `/integration?parentType=heatmapsList&appId=${appId}&index=${indexCopy}&screenpage=${screenpage || 1}`,
        `/app/${appId}/screens/list/${screenpage || 1}`
      )
    },
    [appId, dispatch, indexCopy, screenname, screenpage]
  );

  return (
    <Button
      onClick={clickHandler}
      className="heatmaps-back-btn"
      icon={<LeftOutlined />}
    >
      Screen list
    </Button>
  );
});
export default HeatmapDetails;
