export const replaceSlash = (screenname: string) =>
  screenname?.includes('/') ? screenname.split('/').join('') : screenname;

  // When routing, this function will make sure to properly handle encoded screen names. For now, it only handles the '&' & '/' characters.
  // Added # and @ to the regex to handle those characters as well.
export const encodeSpecialCharsInScreenName = (screenName: string) => {
  const specialCharsRegex = /[&/@#]/g;
  if (specialCharsRegex.test(screenName)) {
      return encodeURIComponent(screenName);
  } 
      return screenName;
};