import moment from 'moment';
import { useMemo } from 'react';
import { useQuery } from 'react-query';
import { RootStateOrAny, useSelector } from 'react-redux';

// utils
import { getBoxDataPercentage } from 'Utils/helpers/commonUtils';
import HeatmapApi from '../apis';

// types
import { TScreenTimeType } from '../WebScreenAnalytics';

export const useScreenBoxAPI = (screenTimeType: TScreenTimeType) => {
    const { appFilter, currentAppReducer } = useSelector((state: RootStateOrAny) => state);
    const { dateSegment } = appFilter;
    const { _id: appid } = currentAppReducer;

    const dateSegmentPrev = useMemo(() => ({
        ...dateSegment,
        value: {
            lower: moment.unix(
                (Math.round(new Date(dateSegment.value.lower).getTime()) -
                    moment(dateSegment.value.upper).diff(dateSegment.value.lower)) /
                1000
            ),
            upper: moment(dateSegment.value.lower).utc().format(),
        },
    }), [dateSegment]);

    const newFormData = useMemo(() => ({
        appid,
        date_range: dateSegment,
        mega_filters: [...appFilter.heatmap.segment],
    }), [appid, dateSegment, appFilter.heatmap.segment]);

    const prevPayload = useMemo(() => ({
        appid,
        date_range: dateSegmentPrev,
        mega_filters: [...appFilter.heatmap.segment],
    }), [appid, dateSegmentPrev, appFilter.heatmap.segment]);

    const { data: screenBoxNewData, isLoading: screenBoxNewLoading } = useQuery(
        ['screenBox', newFormData],
        () => HeatmapApi.fetchHeatmapBox(newFormData),
    );

    const { data: screenBoxPrevData, isLoading: screenBoxPrevLoading } = useQuery(
        ['screenBox', prevPayload],
        () => HeatmapApi.fetchHeatmapBox(prevPayload),
    );

    const newScreenTime = useMemo(() => screenTimeType === 'averageTime' ? screenBoxNewData?.averageTime : screenBoxNewData?.medianTime, [screenBoxNewData, screenTimeType]);
    const prevScreenTime = useMemo(() => screenTimeType === 'averageTime' ? screenBoxPrevData?.averageTime : screenBoxPrevData?.medianTime, [screenBoxPrevData, screenTimeType]);

    const dateString = 'the selected date range';
    const boxData = useMemo(() => {
        const calculateData = (newData: number | undefined, prevData: number | undefined, fallbackValue = 0) => ({
            percent: getBoxDataPercentage(newData, prevData),
            value: newData === -1 ? fallbackValue : newData,
        });

        return {
            screen_count: calculateData(screenBoxNewData?.totalScreenVisit, screenBoxPrevData?.totalScreenVisit),
            bounce_rate: calculateData(screenBoxNewData?.bounceRate, screenBoxPrevData?.bounceRate),
            screen_time: calculateData(newScreenTime, prevScreenTime),
            screen_with_issue: calculateData(screenBoxNewData?.issueScreenCount, screenBoxPrevData?.issueScreenCount),
        };
    }, [newScreenTime, prevScreenTime, screenBoxNewData, screenBoxPrevData]);

    return {
        boxData: boxData || {},
        dateString: dateString || '',
        isLoading: screenBoxNewLoading || screenBoxPrevLoading,
    };
};

export default useScreenBoxAPI;
