import React, { useMemo, memo, useCallback, useState } from 'react';
import { Dropdown, Slider, Button, Divider, Tooltip } from 'antd';
import { round } from 'lodash';
import { useHeatmapContext } from 'components/features/heatmaps/Context/HeatmapContext';
import { getPopupContainer } from 'Utils/helpers/commonUtils';
import {
  HeatmapCogDropdownStyled,
  ResetButtonWrap,
} from 'components/features/heatmaps/HeatmapDetails/HeatmapStyled';
import SettingIcon from './setting-icon.svg';

const CommonSlider = memo(
  ({
    title,
    value,
    onChange,
    min = 1,
    max,
    reverse,
    defaultValue,
    tooltipTitle,
  }) => (
    <>
      <Tooltip placement="rightTop" title={tooltipTitle}>
        {title}
      </Tooltip>
      <Slider
        defaultValue={defaultValue}
        value={value}
        onChange={onChange}
        min={min}
        max={max}
        reverse={reverse}
        tooltipVisible={false}
      />
    </>
  )
);

const HeatmapCogSetting = memo(() => {
  const {
    setHeatmapOpacity,
    heatmapOpacity,
    // setHeatmapRadius,
    // heatmapRadius,
    setHeatmapMax,
    heatmapMaxValue,
    heatmapMax,
    imageOpacity,
    setImageOpacity,
    heatmapRegionSelectionEnabled,
    setHeatmapRegionSelectionEnabled
  } = useHeatmapContext();
  
  const [visible, onVisibleChange] = useState(false);
  const defaultMaxValue = useMemo(
    () => round(0.5 * heatmapMaxValue),
    [heatmapMaxValue]
  );

  const resetHeatmapConfig = useCallback(() => {
    setHeatmapOpacity(50);
    // setHeatmapRadius(50);
    setHeatmapMax(defaultMaxValue);
    setImageOpacity(50);
  }, [defaultMaxValue]);

  const handleRegionSelection = useCallback(() => {
    setHeatmapRegionSelectionEnabled(!heatmapRegionSelectionEnabled);
  }, [heatmapRegionSelectionEnabled, setHeatmapRegionSelectionEnabled])

  const heatMapSettingDropdown = (
    <div className="heatmap-dropdown">
      <CommonSlider
        title="Screenshot opacity"
        value={imageOpacity}
        onChange={setImageOpacity}
      />
      <CommonSlider
        title="Heatmap opacity"
        value={heatmapOpacity}
        onChange={setHeatmapOpacity}
      />
      <CommonSlider // changed to negative for reverse slide
        title="Heatmap sensitivity"
        value={heatmapMax > 0 ? -heatmapMax : heatmapMax}
        defaultValue={-heatmapMax}
        onChange={setHeatmapMax}
        max={-1}
        min={-heatmapMaxValue}
        tooltipTitle="Adjusts heatmap intensity in the paler areas."
      />
      {(
        heatmapOpacity !== 50 ||
        imageOpacity !== 50 ||
        heatmapMax !== defaultMaxValue
        // || heatmapRadius !== 50
        ) && (
        <>
          <Divider className="heatmap-setting-divider" />
          <ResetButtonWrap onClick={resetHeatmapConfig}>
            Reset to default
          </ResetButtonWrap>
        </>
      )}
    </div>
  );
  return (
    <HeatmapCogDropdownStyled>
      <Dropdown
        overlay={heatMapSettingDropdown}
        placement="bottomRight"
        trigger={['click']}
        className="heatmap-setting-icon"
        visible={visible}
        onVisibleChange={onVisibleChange}
        getPopupContainer={getPopupContainer}
      >
        <Button icon={<SettingIcon />} type="ghost" data-intercom-target="Setting"/>
      </Dropdown>
    </HeatmapCogDropdownStyled>
  );
});
export default HeatmapCogSetting;
