/* eslint-disable no-nested-ternary */
import React, { memo, useMemo, useCallback, useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { uniq } from 'lodash';
import ReactLoader from 'components/common/reactLoading';
import { useHeatmapContext } from 'components/features/heatmaps/Context/HeatmapContext';
import { gesturesTypesWithValue } from 'components/features/heatmaps/constants';
import {
  useAreaSpecificHeatmapGestures,
  useHeatmapImagesGestures,
  useHeatmapScreenheatmaps,
} from 'components/features/heatmaps/hooks';
import { ScreenTabLayoutRightStyled } from 'components/features/heatmaps/HeatmapDetails/HeatmapStyled';
import { trackPageViews } from 'redux/actions/trackingReport';
import { compactNotation } from 'Utils/helpers/commonUtils';
import { formattedFilters} from 'Utils/ScreenPageFilter';
import { readableTimeFormatter } from 'Utils/DateConversion/dateConversionUtils';
import HeatmapImageMap from './HeatmapImageMap';
import HeatmapCogSetting from './HeatmapCogSetting';

const getParams = (attribute, operator = 'equal', value = 'True') => ({
  attribute,
  operator,
  value,
});

const launchQuitList = ['is_first_screen', 'is_last_screen']
const defaultHeatmapGesturePlot = { data: [] };

const HeatmapCard = memo(() => {
  const dispatch = useDispatch();
  const { orientation, quickGestureOptions, gestureTypes, deviceClass, regionCoordinates } =
    useHeatmapContext();
  const { screenname, appId } = useSelector((state) => state.urlReducer);
  const {
    dateSegment,
    heatmap: { segment },
  } = useSelector((state) => state.appFilter);
  const { startX, startY, endX, endY } = regionCoordinates || {};
  const isLaunchQuit = useCallback((el) => launchQuitList.indexOf(el) > -1, [])
  const isLaunchQuitThere = useCallback((opt) => opt.some((el) => isLaunchQuit(el)), [isLaunchQuit]);

  const changedGestureOptions = useMemo(
    () =>
      [...quickGestureOptions].map((option) => {
        let optionCopy = option;
        switch (optionCopy) {
          case 'is_first_screen':
            optionCopy = 'is_first_gesture';
            break;
          case 'is_last_screen':
            optionCopy = 'is_last_gesture';
            break;
          default:
            break;
        }
        return optionCopy;
      }),
    [quickGestureOptions]
  );

  const quickGestureOptionsCopy = useMemo(() => {
    let data = {};
    let options = [...quickGestureOptions];
    if (isLaunchQuitThere(options)) options = changedGestureOptions
    uniq(options)
      .map((v) => {
        data = { ...data, [v]: true };
        return data;
      });
    return data;
  }, [changedGestureOptions, isLaunchQuitThere, quickGestureOptions]);

  const launchQuitSegment = useMemo(() => {
    let filterLastQuit = quickGestureOptions.filter((el) => isLaunchQuit(el));
    filterLastQuit = filterLastQuit.length ? filterLastQuit.map((attr) => getParams(attr)) : [];
    return filterLastQuit;
  }, [isLaunchQuit, quickGestureOptions]);

  const gestureType = useMemo(
    () => (gestureTypes.map((type) => gesturesTypesWithValue[type])),
    [gestureTypes]
  );

  const gesturesFilters = useMemo(
    () => ({
      ...{ screenname },
      ...{ device_class: deviceClass },
      ...{ orientation },
      ...{gesture_type: gestureType},
      ...quickGestureOptionsCopy,
    }),
    [screenname, deviceClass, orientation, gestureType, quickGestureOptionsCopy]
  );

  const formattedSegment = useMemo(()=> formattedFilters(segment) || [], [segment]) 
  const coordinates = useMemo(() => {
    if (startX && startY && endX && endY) {
      return [
        {
          'attribute': 'x_bin',
          "operator": "between",
          "value": {
            "lower": startX,
            "upper": endX
          }
        },
        {
          'attribute': 'y_bin',
          "operator": "between",
          "value": {
            "lower": startY,
            "upper": endY
          }
        },
      ]
    }
    return [];
}, [endX, endY, startX, startY])

  const gesturePayload = useMemo(
    () => ({
      appid: appId,
      date_range: dateSegment,
      filters: gesturesFilters,
      mega_filters: [...formattedSegment, ...launchQuitSegment],
    }),
    [appId, dateSegment, gesturesFilters, launchQuitSegment, formattedSegment]
  );

  const areaSpecificGesturePayload = useMemo(() =>
  ({
    appid: appId,
    date_range: dateSegment,
    filters: gesturesFilters,
    mega_filters: [...segment, ...launchQuitSegment, ...coordinates],
  }),
    [appId, dateSegment, gesturesFilters, launchQuitSegment, segment, coordinates]
  )
  const deviceClassFilter = useMemo(
    () => [getParams('device_class', 'in', [deviceClass])],
    [deviceClass]
  );
  const orientationPayload = useMemo(
    () => [getParams('orientation', 'equal', orientation)],
    [orientation]
  );
  const filterSegmentByKey = useCallback(
    (attribute) => [...segment].filter((v) => v.attribute === attribute),
    [segment]
  );
  const heatmapsScreenshotsFilter = useMemo(
    () => [
      ...deviceClassFilter,
      ...orientationPayload,
      ...filterSegmentByKey('device_os_version'),
      ...filterSegmentByKey('app_version'),
      ...filterSegmentByKey('device_platform'),
    ],
    [deviceClassFilter, orientationPayload, filterSegmentByKey]
  );
  const screenshotsPayload = useMemo(
    () => ({
      appid: appId,
      screen_name: screenname,
      mega_filters: heatmapsScreenshotsFilter,
      date_range: dateSegment,
    }),
    [appId, screenname, dateSegment, heatmapsScreenshotsFilter]
  );
  const callGestureApi = useMemo(() => gestureTypes.length > 0, [gestureTypes]);
  let heatmapGesturePlot;
  const {
    data: heatmapGestures,
    isLoading: isHeatmapGesturesLoading,
    isRefetching: isHeatmapGesturesFetching,
  } = useHeatmapImagesGestures(gesturePayload, callGestureApi);
  const { data, isLoading: isheatmapScreenShotsLoading } = useHeatmapScreenheatmaps(screenshotsPayload);
  const heatmapScreenShots = data?.body;

  if (heatmapGestures?.data) heatmapGesturePlot = heatmapGestures?.data;
  if (!callGestureApi) heatmapGesturePlot = defaultHeatmapGesturePlot.data;

  const {
    data: areaSpecificHeatmapGestures,
    refetch: refetchAreaSpecificGestures,
    isLoading: isAreaSpecificGesturesLoading,
    isRefetching: isAreaSpecificGesturesFetching,
  } = useAreaSpecificHeatmapGestures(areaSpecificGesturePayload);

  const isTooltipMetricLoading = useMemo(() => 
  isAreaSpecificGesturesLoading ||
  isAreaSpecificGesturesFetching, [
    isAreaSpecificGesturesLoading,
    isAreaSpecificGesturesFetching,
  ]);

  const { data: responseData } = areaSpecificHeatmapGestures || {}
  const isLoading = useMemo(
    () =>
      isheatmapScreenShotsLoading ||
      isHeatmapGesturesLoading ||
      isHeatmapGesturesFetching,
    [
      isheatmapScreenShotsLoading,
      isHeatmapGesturesLoading,
      isHeatmapGesturesFetching,
    ]
  );

  const sendAreaSelectEvents = () => {
  dispatch(
      trackPageViews(null, {
        eventName: 'hm_screen_area_select',
        track_type: 'event',
        eventProperty: {
          screen_name: `${screenname}`,
          area_metrics: {
            gestures: {
              taps: compactNotation(responseData[0]?.tapCount || 0),
              'rage taps': compactNotation(responseData[0]?.rageTapCount || 0),
              swipes: compactNotation(responseData[0]?.swipeCount || 0),
              zoom: compactNotation(responseData[0]?.zoomCount || 0),
            },
            'gesture count': compactNotation(responseData[0]?.value || 0),
            user: compactNotation(responseData[0]?.userCount || 0),
            'gesture time in sec': readableTimeFormatter(
              responseData[0]?.gestureTime || 0
            ),
          },
        },
      })
    );
  };

  useEffect(() => {
    if(coordinates?.length) {
      refetchAreaSpecificGestures();
    }
  }, [coordinates])

  useEffect(()=>{
    if(responseData){
      sendAreaSelectEvents()
    }
  }, [responseData])

  useEffect(() => {
    dispatch(
      trackPageViews(null, {
        eventName: 'hm_navigate_to_heatmap', track_type: 'event',
        eventProperty: {
          screenname,
        }
      }
      )
    );
  }, [dispatch, screenname])

  const renderComponent = useMemo(() => {
    if (heatmapScreenShots)
      return (
        <HeatmapImageMap
          heatmapScreenShots={heatmapScreenShots}
          heatmapGesturePlot={heatmapGesturePlot}
          isLoading={isLoading}
          isTooltipMetricLoading={isTooltipMetricLoading}
          areaSpecificHeatmapGestures={areaSpecificHeatmapGestures}
        />
      );
    return (
      <div className="section-box-loader">
        <ReactLoader />
      </div>
    );
  }, [heatmapScreenShots, heatmapGesturePlot, isLoading, isTooltipMetricLoading, areaSpecificHeatmapGestures]);

  return (
    <ScreenTabLayoutRightStyled>
      {renderComponent}
      <HeatmapCogSetting />
    </ScreenTabLayoutRightStyled>
  );
});
export default HeatmapCard;
