import React, { memo, useCallback, useEffect, useMemo, useState } from 'react';
import { useSelector } from 'react-redux';
import Router from 'next/router';
import useColumns from 'components/features/heatmaps/hooks/useColumns';
import { useScreensImageList } from 'components/features/heatmaps/hooks';
import { urlSegmentEncoder } from 'Utils/helpers/urlSegmentEncoder';
import useLocalStorage from 'hooks/useLocalStorage';
import { screensParentType } from 'components/features/heatmaps/constants';
import { differenceBy, isEqual } from 'lodash';
import ExportScreenCSV from 'components/shared/ExportCSV/Download';
import { HybridTable, StylesProvider } from 'uxcam-frontend-components';
import { useIsAppType } from 'hooks/useIsAppType';
import UpdateIndicator from 'components/common/UpdateIndicator';
import { useScreenTableHelper } from './utils';
import defaultHeaders from './mock/screenHeaders.json';

import ScreenFilter from './ScreenFilter';
import ColumnUpdate from './ColumnUpdate';

// uncomment for new table implementation
import {
  ToolbarWrapper,
  ToolbarLeft,
  ToolbarRight,
} from './styles';
import { encodeSpecialCharsInScreenName } from '../utils';

export const defaultSortBy = [{ id: 'visitCount', desc: true }];

const updatingHeaders = ['avgScreenTimePerVisit', 'avgScreenTimePerUser'];

const displayNameColumn = {
  "attribute": "displayName",
  "title": "Updated Name",
  "isVisible": false,
  "isDraggable": false,
  "isSortable": true,
  "titleInfo": ""
}

const ScreenPage = ({
  setServerSortedOrder,
  serverSortedOrder,
  screenData,
  isLoading,
  isFetching,
  reqBody,
  lastUpdate,
  onRefresh,
  setSearchFilter,
  isServerSideMode = false,
  apiPagination,
  serverPageIndex,
  setServerPageIndex,
}) => {
  const {
    appFilter: {
      dateSegment,
      heatmap: { segment: filters = [] },
    },
    urlReducer: { appId, screenpage, parentType }
  } = useSelector(({ appFilter, urlReducer }) => ({
    appFilter,
    urlReducer,
  }));

  // uncomment for new table implementation
  const screenPageNumber =  useMemo(()=> Number(screenpage || 1), [screenpage]);
  const [cachedHeaders, setCachedHeaders] = useLocalStorage('screenHeaders', defaultHeaders);
  const [defaultCachecHeaders] = useLocalStorage('defaultScreenHeaders', defaultHeaders);

  const tableHeaders = useMemo(() => {
    if(isEqual(defaultHeaders, defaultCachecHeaders)) {
      return cachedHeaders
    }
    const newHeaders = differenceBy(defaultHeaders, cachedHeaders, 'attribute');
    if (newHeaders.length > 0) {
      return [...cachedHeaders, ...newHeaders];
    }
    const updatedHeaders = differenceBy(defaultHeaders, cachedHeaders, 'title');
    if (updatedHeaders.length > 0) {
      const tempCachedheaders = cachedHeaders.map(item => {
        if (updatingHeaders.includes(item?.attribute)) {
          return {
            ...item,
            title: defaultHeaders.find(updatedItem => updatedItem.attribute === item.attribute).title,
            titleInfo: defaultHeaders.find(updatedItem => updatedItem.attribute === item.attribute).titleInfo
          }
        }
        return item;
      })
      return tempCachedheaders;
    }
    return defaultHeaders
    
  }, [cachedHeaders, defaultCachecHeaders]);

  const screenHeaders = useMemo(() => {
    if (tableHeaders.some(item => item.attribute === 'displayName')) {
      return tableHeaders;
    }
    return [...tableHeaders, ...[displayNameColumn]]
  }, [tableHeaders]);

  const [headers, setHeaders] = useState(screenHeaders);

  const [globalFilter, setGlobalFilter] = useState('');
  const [sortOrder, setSortedOrder] = useState(defaultSortBy);

  // specifically for client side pagination
  const [pagination, setPagination] = useState({
    pageIndex: 1,
    pageSize: 20,
  });
  const { handlePagination, chunkArray } = useScreenTableHelper();

  // Server pagination object using props from parent
  const serverPagination = useMemo(() => ({
    pageIndex: serverPageIndex,
    pageSize: 20,
  }), [serverPageIndex]);

  const setServerPagination = useCallback((newPagination) => {
    const newPageIndex = typeof newPagination === 'function'
      ? newPagination(serverPagination).pageIndex
      : newPagination.pageIndex;
    setServerPageIndex(newPageIndex);
  }, [serverPagination, setServerPageIndex]);

  // Determine batch-based pagination
  // Each API call returns up to 1001 items, covering 50 pages (1000 items + 1 overlap)
  // Batch 1 (pages 1-50): Initial request, no page param
  // Batch 2 (pages 51-100): page=51 request
  // Batch 3 (pages 101-150): page=101 request
  const batchSize = 50;
  const currentBatch = Math.ceil(serverPageIndex / batchSize); // 1-50 = batch 1, 51-100 = batch 2
  const isExtendedServerPage = isServerSideMode && currentBatch > 1;

  // Calculate the index within the current batch (0-49)
  // Page 51 -> index 0, Page 52 -> index 1, ..., Page 100 -> index 49
  const indexWithinBatch = (serverPageIndex - 1) % batchSize;
  const extendedPageOffset = indexWithinBatch * 20; // Each page shows 20 items

  // Use the isServerSideMode flag from parent to determine client/server side handling
  // This prevents infinite loops when filtered results change the data length
  const isClientSide = useMemo(() => !isServerSideMode, [isServerSideMode]);
  const isServerSideSearch = useMemo(() => isServerSideMode, [isServerSideMode]);



  const columns = useColumns(headers);

  useEffect(() => {
    setCachedHeaders(screenHeaders);
  }, [setCachedHeaders])

  const isWebApp = useIsAppType( 'web' )

  const onSelectScreenRow = useCallback((row) => {
    if ( isWebApp )  {
      const { screenname: screenName } = row;
      const encoded = encodeURIComponent(screenName);
      const query = `appId=${appId}&parentType=webHeatmaps&screen_name=${encoded}&reportId=new`;
      let url = `/app/${appId}/web-heatmap/new?screen_name=${encoded}`;
      url = urlSegmentEncoder(url, filters)
  
      Router.push(`/integration?${query}`, url);
      return
    }
    const { screenname: screenName } = row;
    const screenUpdated = encodeSpecialCharsInScreenName(screenName);
    const query = `appId=${appId}&parentType=${screensParentType}&screenname=${screenUpdated}&screenpage=${screenpage}`;
    let url = `/app/${appId}/screens/details/${screenUpdated}?`;
    url = urlSegmentEncoder(url, filters)

    Router.push(`/integration?${query}`, url);
  }, [appId, filters, screenpage, isWebApp])

  const updateScreenHeaders = (updatedHeaders) => {
    if (updatedHeaders.some(item => item.attribute === 'displayName')) {
      setHeaders(updatedHeaders);
    }
    else setHeaders([...updatedHeaders, ...[displayNameColumn]])
  };

  // reset pagination on date segment change
  useEffect(() => {
    if (parentType !== 'heatmapsList') return;
    if (screenPageNumber !== 1 && !screenData) {
      handlePagination(1);
    }
    setGlobalFilter('');
  }, [dateSegment]);

  // Handle server-side search filter
  useEffect(() => {
    if (!setSearchFilter) return;

    if (isServerSideSearch) {
      // Pass empty string when cleared, trim whitespace for actual searches
      setSearchFilter(globalFilter ? globalFilter.trim() : '');
    } else {
      // Clear server-side filter when switching back to client-side mode
      setSearchFilter('');
    }
  }, [globalFilter, isServerSideSearch, setSearchFilter]);

  // handles pagination index update on route page change
  useEffect(() => {
    if (isClientSide) {
      setPagination({ ...pagination, pageIndex: screenPageNumber - 1 });
    } else {
      setServerPagination({ ...serverPagination, pageIndex: screenPageNumber });
    }
  }, [screenPageNumber, isClientSide])

  // 
  const groupedArray = useMemo(() => chunkArray(screenData || [], 20), [screenData]);

  const rowsData = useMemo(
    () => screenData?.map((item) => ({
      ...item,
      onRowClick: () => onSelectScreenRow(item),
    })) || [],
    [onSelectScreenRow, screenData]
  );

  const serverRowsData = useMemo(() => {
    // For extended pages (51+), API returns up to 1001 items starting from the requested page
    if (isExtendedServerPage) {
      // Calculate which slice of 20 items to show from the 1001 items returned
      const startIndex = extendedPageOffset;
      const endIndex = startIndex + 20;
      const pageData = screenData?.slice(startIndex, endIndex) || [];
      return pageData.map((item) => ({
        ...item,
        onRowClick: () => onSelectScreenRow(item),
      }));
    }
    // For pages 1-50, chunk from the cached 1001 items
    return groupedArray[serverPagination.pageIndex - 1]?.map((item) => ({
      ...item,
      onRowClick: () => onSelectScreenRow(item),
    })) || [];
  }, [groupedArray, onSelectScreenRow, serverPagination.pageIndex, isExtendedServerPage, screenData, extendedPageOffset]);
  const localSearchedData = useMemo(() => {
    // For server-side mode, always use serverRowsData (search is handled by backend)
    if (isServerSideSearch) {
      return serverRowsData;
    }

    // For client-side mode without search, use rowsData
    if (!globalFilter) {
      return rowsData;
    }

    // For client-side mode with search, filter locally
    const searchTerm = globalFilter.toLowerCase();

    const filteredData = screenData?.filter((item) => {
      // Cache lowercase conversions to avoid repeated calls
      const displayName = item.displayName?.toLowerCase() || '';
      const screenname = item.screenname?.toLowerCase() || '';
      return displayName.includes(searchTerm) || screenname.includes(searchTerm);
    });

    return filteredData?.map((item) => ({
      ...item,
      onRowClick: () => onSelectScreenRow(item),
    })) || [];
  }, [globalFilter, isServerSideSearch, rowsData, screenData, serverRowsData, onSelectScreenRow]);

  const visibleScreenNames = useMemo(() => {
    if (isServerSideMode) {
      return localSearchedData.map(item => item.screenname);
    }

    // Check if it's a large dataset that will likely switch to server-side mode
    // or if we just want to optimize for large client-side lists too
    const isLargeDataset = (screenData?.length >= 1001) || (apiPagination?.total > 1000);

    if (isLargeDataset) {
      const startIndex = (pagination.pageIndex - 1) * pagination.pageSize;
      const endIndex = startIndex + pagination.pageSize;
      return localSearchedData.slice(startIndex, endIndex).map(item => item.screenname);
    }

    return screenData?.map(item => item.screenname) || [];
  }, [isServerSideMode, localSearchedData, screenData, apiPagination, pagination]);

  useScreensImageList({
    screenNames: visibleScreenNames,
    paginationLimit: pagination.pageSize,
    screensListReqBody: reqBody,
    screenSearchText: '',
  })

  // since handleRouteUpdate is not being triggered for server side enabled
  useEffect(() => {
    if (parentType !== 'heatmapsList') return;
    if(serverPagination.pageIndex && !isClientSide) {
      handlePagination(serverPagination.pageIndex);
    }
  }, [serverPagination.pageIndex])

  useEffect(() => {
    let localStoredScreenSort = '';
    try {
      localStoredScreenSort = localStorage.getItem('screenSortBy');
    } catch (err) {
      // silent fail
    }
    if(localStoredScreenSort !== 'undefined' && localStoredScreenSort) {
      setSortedOrder(JSON.parse(localStoredScreenSort))
    }
  }, [])

  return (
    <>
      <ToolbarWrapper>
        <ToolbarLeft
        data-intercom-target="Search screens"
        >
          <ScreenFilter
            globalFilter={globalFilter}
            setGlobalFilter={(value) => {
              setGlobalFilter(value);
              handlePagination(1);
            }}
            isServerSideSearch={isServerSideSearch}
          />
          <UpdateIndicator
            lastUpdate={lastUpdate}
            onClick={onRefresh}
            isRefreshing={isFetching}
            style={{marginLeft: '12px'}}
          />
        </ToolbarLeft>
        <ToolbarRight
          data-intercom-target="Filter screens"
        >
          <ColumnUpdate updateScreenHeaders={updateScreenHeaders} defaultHeaders={defaultHeaders}/>
          <ExportScreenCSV globalFilter={globalFilter} />
        </ToolbarRight>
      </ToolbarWrapper>
      <StylesProvider>
        <HybridTable
          data={localSearchedData}
          columns={columns}
          sorting={isClientSide ? sortOrder : serverSortedOrder}
          setSorting={(sortFn) => {
            try {
              localStorage.setItem('screenSortBy', JSON.stringify(sortFn()));
            } catch (err) {
              // silent fail
            }
            handlePagination(1);
            if (isClientSide) {
              setSortedOrder(sortFn());
            } else {
              setServerPageIndex(1);
              setServerSortedOrder(sortFn());
            }
          }}
          resizeMode="onChange"
          isLoading={isLoading || isFetching}
          enableServerSideHandling={!isClientSide}
          pagination={{
            ...(isClientSide ? pagination : serverPagination),
            // For server-side mode, totalPagination should be total ITEMS (not pages)
            // HybridTable calculates pages internally from items / pageSize
            totalPagination: apiPagination?.total
              ?? (isClientSide ? localSearchedData?.length : (groupedArray.length * 20))
              ?? 0,
          }}
          setPagination={isClientSide ? null : setServerPagination}
          handleRouteUpdate={(page) => {
            // NOTE: this function only triggers for client side pagination (needs debugging)
            handlePagination(page);
            setPagination({ ...pagination, pageIndex: page - 1 });
          }}
          stickyHeaders={['screenname']}
          tableHeight='100%'
          tableWidth='100%'
          emptyText={{message: 'No screens match the current filters.'}}
        />
      </StylesProvider>
    </>
  );
};

export default memo(ScreenPage);
