import React, { memo, useMemo, useCallback, useEffect, useState } from 'react';
import { useSelector } from 'react-redux';
import { Row, Col } from 'antd';
import { useQueryClient } from 'react-query';

import {
  HeatmapDetailWrapper,
} from 'components/features/heatmaps/HeatmapDetails/HeatmapStyled';
import { useHeatmapContext } from 'components/features/heatmaps/Context/HeatmapContext';
import ReactLoader from 'components/common/reactLoading';
import { formattedFilters} from 'Utils/ScreenPageFilter';
import { useScreenDeviceClass } from 'components/features/heatmaps/hooks';
import HeatmapCard from './HeatmapCard';
import HeatmapGesturesFilter from './HeatmapsFilter';

const ScreenDetailHeatmaps = memo(() => {
  const {
    setDeviceClass,
    setDeviceClassOption,
    deviceClass,
    deviceClassOption
  } = useHeatmapContext();
  const [isDeviceClassCall, setIsDeviceClassCall] = useState(false)
  const queryClient = useQueryClient();
  const {
    appFilter: {
      dateSegment,
      heatmap: { segment },
    },
    urlReducer: { screenname, appId },
  } = useSelector(({ appFilter, urlReducer, currentOrgReducer }) => ({
    appFilter,
    urlReducer,
    currentOrgReducer,
  }));
  
  const payload = useMemo(
    () => ({
      appid: appId,
      screen_name: screenname,
      mega_filters: formattedFilters(segment) || [],
      date_range: dateSegment,
    }),
    [appId, screenname, segment, dateSegment]
  );
  const reqBodyAppDeviceClass = useMemo(
    () => ({
      appid: appId,
      mega_filters: [...segment],
      date_range: dateSegment,
    }),
    [appId, dateSegment, segment]
  );
  const appDeviceClassData = queryClient.getQueryData([
    'app-device-class',
    reqBodyAppDeviceClass,
  ]);
  useEffect(() => {
    if (appDeviceClassData) {
      const deviceClassCombined = [
        ...appDeviceClassData['android'],
        ...appDeviceClassData['ios'],
      ].sort((a, b) => b.gestures - a.gestures);
      const [deviceWithGestureCount = {}] = deviceClassCombined || [];
      if (deviceWithGestureCount.deviceclass) setDeviceClass(deviceWithGestureCount.deviceclass);
      setIsDeviceClassCall(true)
    }
  }, [appDeviceClassData]);
  const onSuccessDeviceClass = useCallback((data) => {
    const dataSorted = data?.length ? data.sort((a, b) => b.gestures - a.gestures) : []
    setDeviceClassOption(dataSorted);
  }, [setDeviceClassOption]);
  useEffect(() => {
    if(!appDeviceClassData && !isDeviceClassCall && deviceClassOption?.length)
      setDeviceClass(deviceClassOption[0].deviceclass)
  }, [appDeviceClassData, deviceClassOption])
  const { data: deviceClassOptionData } = useScreenDeviceClass(payload);
  useEffect(() => {
    if(deviceClassOptionData) onSuccessDeviceClass(deviceClassOptionData)
  }, [onSuccessDeviceClass, deviceClassOptionData])
  if (!deviceClass) return <ReactLoader />;
  return (
    <HeatmapDetailWrapper className="screeninfo-box-wrapper">
      <Row>
        <Col lg={18}>
          <HeatmapCard />
        </Col>
        <Col lg={6}>
          <HeatmapGesturesFilter />
        </Col>
      </Row>
    </HeatmapDetailWrapper>
  );
});

export default ScreenDetailHeatmaps;
