/* eslint-disable react/no-array-index-key */
/* eslint-disable react/jsx-props-no-spreading */
import React, {
  memo,
  useEffect,
  useRef,
  useState,
  useMemo,
  useCallback,
} from 'react';
import { useSelector, useDispatch } from 'react-redux';
import classNames from 'classnames';
import Heatmap from 'heatmap.js/build/heatmap';
import { round } from 'lodash';
import {
  InfoCircleOutlined,
  LeftOutlined,
  RightOutlined,
  WarningOutlined,
} from '@ant-design/icons';
import Swiper from 'react-id-swiper';
import $ from 'jquery';
import styled from 'styled-components';

import { trackPageViews } from 'redux/actions/trackingReport';
import { useHeatmapContext } from 'components/features/heatmaps/Context/HeatmapContext';
import ReactLoader from 'components/common/reactLoading';
import {
  HeatmapScreenStyled,
  ErrorTextStyled,
  HeatmapImageStyled,
  ImageStyled,
} from 'components/features/heatmaps/HeatmapDetails/HeatmapStyled';
import HeatmapTooltipContent from 'components/features/heatmaps/hooks/HeatmapTooltipElement';

const HeatmapCanvasTooltip = styled.div`
  left: 15px;
  top: 15px;
  border-radius: 5px;
  box-shadow: 1px 1px 10px rgba(0, 0, 0, 0.25);
  background: #131E33;
  color: #FFFFFF;
  font-size: 14px;
  padding: 10px;
  line-height: 24px;
  position: absolute;
  z-index: 999999;
  opacity: 1;
  text-align: start;
  width: ${( { heatmapRegionSelectionEnabled } ) => heatmapRegionSelectionEnabled ? '230px' : '250px'};
`;

const RegionSelectionCanvas = styled.canvas`
  display: block;
  pointer-events: none;
  position: absolute;
  left: 0;
  top: 0;
`

const HeatmapImageMap = memo(
  ({ isLoading, isTooltipMetricLoading, heatmapScreenShots, heatmapGesturePlot = [], areaSpecificHeatmapGestures }) => {
    const {
      deviceClass,
      deviceClassOption,
      orientation,
      heatmapOpacity,
      heatmapMax,
      setHeatmapMax,
      setHeatmapMaxValue,
      imageOpacity,
      regionCoordinates,
      setRegoinCoordinates,
    } = useHeatmapContext();
    const dispatch = useDispatch();
    const [imageLoaded, setImageLoaded] = useState(false);
    const { screenname } = useSelector((state) => state.urlReducer);
    const { bottomBarClassFlag } = useSelector((state) => state.commonReducer);

    const heatmapCanvas = document.querySelector('.heatmap-canvas');

    const heatmapScreenShotsLen = heatmapScreenShots?.length > 1;
    const heatmapInitialImage = heatmapScreenShots?.[0];
    const heatmapRef = useRef(null);
    const swiperRef = useRef(null);
    const regionSelectionCanvas = useRef(null);
    const heatmapCanvasTooltipRef = useRef(null);
    const dragStateRef = useRef('idle') // idle , dragging, drawn
    
    const [tooltipValues, setTooltipValues] = useState(null);
    const [tooltipPosition, setTooltipPosition] = useState(null);

    const params = {
      pagination: {
        el: '.swiper-pagination',
        type: 'fraction',
      },
      loop: true,
    };

    const doResize = useCallback(({ width, height }) => {
      const $el = $('#heatmap-image');
      const elHeight = $el.outerHeight();
      const elWidth = $el.outerWidth();
      const scale =
        orientation === 0
          ? Math.min((width - 125) / elHeight, (height - 125) / elWidth)
          : Math.min(width / elWidth, (height - 35) / elHeight);
      const transform = `translate( -50%, -50%)  rotate(${orientation === 0 ? -90 : 0
        }deg) scale(${scale})`;
      $el.css({ transform });
    }, [orientation]);

    const scaleHeatMap = () => {
      const $wrapper = $('#heatmap-image-wrapper');
      doResize({ width: $wrapper.width(), height: $wrapper.height() });
    };

    const handleImageLoaded = () => {
      document.body.onresize = () => scaleHeatMap();
      setImageLoaded(true);
    };

    const sndEvent = useCallback(() =>
      dispatch(
        trackPageViews(null, {
          eventName: 'hm_toggle_through_screenshots',
          track_type: 'event',
          eventProperty: {
            screenname: `${screenname}`,
          },
        })
    ), [dispatch, screenname]);

    const swipeHandler = useCallback((swipeDir) => {
      if (swiperRef?.current?.swiper) {
        sndEvent();
        if (swipeDir === 'right') swiperRef.current.swiper.slideNext();
        else swiperRef.current.swiper.slidePrev();
      }
    }, [sndEvent]);

    const noGestureErrorMessage = useMemo(
      () =>
        deviceClassOption?.length &&
          deviceClassOption.findIndex((el) => el.deviceclass === deviceClass) <=
          -1
          ? 'You can change the device class to see meaningful heatmaps'
          : 'No gestures on this screen for this device class and the applied filters',
      [deviceClass, deviceClassOption]
    );

    const nearestValidPoint = useCallback(
      (xi, yi, points) =>
        points.reduce(
          (acc, curr, index) => {
            const [xa, yb] = curr;
            const binSize = 20
            const isLessThanBinSize =
              Math.abs(xi - xa) <= binSize / 2 &&
              Math.abs(yi - yb) <= binSize / 2;
            if (isLessThanBinSize) acc.nearestIndex = index
            return acc
          },
          { nearestPoints: {}, nearestIndex: -1 }
        ).nearestIndex,
      []
    );

    const updateTooltip = useCallback(
      (offsetx, xt, offsety, yt) => {
        const x = offsetx || xt;
        const y = offsety || yt;
        const nearestIndex = nearestValidPoint(x, y, [...heatmapGesturePlot].map((points) => [points.x, points.y]));
        setTooltipValues({
          x,
          y,
          nearestPoint: heatmapGesturePlot[nearestIndex]
        })
      },
      [heatmapGesturePlot, nearestValidPoint]
    );

    const updateAreaTooltip = useCallback(
      (offsetx, offsety, nearestPoint) => {
        const x = offsetx || 0;
        const y = offsety || 0;

        setTooltipValues({
          x,
          y,
          nearestPoint
        })
      },
      []
    );

    const setTooltipCoordinates = useCallback((clientY, rectLength, rectBreadth) => {
      const heatmapRegionSelectionEnabled = dragStateRef.current === 'drawn';
      const canvasArea = heatmapRegionSelectionEnabled ?
        regionSelectionCanvas?.current?.getBoundingClientRect() :
        heatmapCanvas?.getBoundingClientRect();
      const rectHeight = heatmapRegionSelectionEnabled ? Math.abs(rectLength) + 20 : 20;
      const rectWidth = heatmapRegionSelectionEnabled ? Math.abs(rectBreadth) : 0;
      const {top, height} = canvasArea;

      const tooltipDistanceFromYAxis = clientY - top;
      const tooltipFlippedY = tooltipDistanceFromYAxis  > height / 1.5;
      
      setTooltipPosition({
        tooltipFlippedY,
        rectHeight,
        rectWidth
      });
    }, [heatmapCanvas]);

    const tooltipHandler = useCallback(() => {
      if (!heatmapCanvas) return;
      heatmapCanvas.onmousemove = (ev) => {
        if (isLoading || dragStateRef.current === 'dragging' || dragStateRef.current === 'drawn') return;
        setTooltipCoordinates(ev.clientY);
        updateTooltip(ev.offsetX, ev.layerX, ev.offsetY, ev.layerY);
      };
      heatmapCanvas.onmouseleave = () => {
        if (isLoading || dragStateRef.current === 'dragging' || dragStateRef.current === 'drawn') return;
        setTooltipValues(null);
      };
    }, [heatmapCanvas, isLoading, setTooltipCoordinates, updateTooltip]);

    const regionSelection = useCallback(() => {
      let startX;
      let startY;
      let endX;
      let endY;
      let width;
      let height;

      const heatmapContainer = document.querySelector('#heatmap-image');
      if (!heatmapContainer || !regionSelectionCanvas?.current) return;
      const ctx = regionSelectionCanvas?.current?.getContext("2d");

      document.onclick = (event) => {
        if(event.target.localName !== 'canvas') {
          if(dragStateRef.current === 'drawn') {
            dragStateRef.current = 'idle';
            setTooltipValues(null);
            setTooltipCoordinates(null);
            ctx.clearRect(0, 0, regionSelectionCanvas?.current?.width, regionSelectionCanvas?.current?.height);
            return;
          }
          if(dragStateRef.current === 'dragging') {
            dragStateRef.current = 'drawn';
            setRegoinCoordinates({ startX, startY, endX, endY });
            setTooltipCoordinates(event.clientY, height, width);
            startX = 0; startY = 0; endX = 0; endY = 0;
          }
        }
      }

      heatmapContainer.onmousedown = (event) => {
        if(isLoading || event.target.localName !== 'canvas') return;
        startX = event.offsetX;
        startY = event.offsetY;
        dragStateRef.current = 'dragging';
      };

      heatmapContainer.onmousemove = (event) => {
        if (isLoading || dragStateRef.current === 'idle' || dragStateRef.current === 'drawn') return;

        setTooltipValues(null);
        // get the current mouse position
        endX = event.offsetX;
        endY = event.offsetY;

        // clear the canvas
        ctx.clearRect(0, 0, regionSelectionCanvas?.current?.width, regionSelectionCanvas?.current?.height);

        // calculate the rectangle width/height based on starting vs current mouse position
        width = endX - startX;
        height = endY - startY;

        // designs for rectangle drawn
        ctx.setLineDash([5, 5]);
        ctx.fillStyle = `rgba(9, 15, 25, 0.5)`;
        ctx.strokeStyle = '#ffffff';
        ctx.fillRect(startX, startY, width, height);

        // draw a new rect from the start position to the current mouse position
        ctx.strokeRect(startX, startY, width, height);
      };

      heatmapContainer.onmouseup = (event) => {
        if(isLoading || event.target.localName !== 'canvas') return;
      
        if((!endX && !endY) || endY === startY) { // check case for only click
          dragStateRef.current = 'idle';
          endX = 0;
          ctx.clearRect(0, 0, regionSelectionCanvas?.current?.width, regionSelectionCanvas?.current?.height);
          setTooltipValues(null);
          return;
        }

        if (dragStateRef.current === 'dragging') {
          if (Math.abs(endX) < 1) {
            setTooltipValues(null);
            setTooltipCoordinates(null);
            return;
          }
          dragStateRef.current = 'drawn';

          setRegoinCoordinates({ startX, startY, endX, endY });
          setTooltipCoordinates(event.clientY, height, width);
          startX = 0; startY = 0; endX = 0; endY = 0;
        }
      };
      // heatmapContainer.onmouseleave = (event) => {
      //   if (isLoading || dragStateRef.current === 'drawn') return;
      //   if (dragStateRef.current === 'dragging') {
      //     dragStateRef.current = 'drawn';
      //     setRegoinCoordinates({ startX, startY, endX, endY });
      //     setTooltipCoordinates(event.clientY, height, width);
      //     return;
      //   } 
      //   setTooltipValues(null);
      // };
    }, [isLoading, setRegoinCoordinates, setTooltipCoordinates]);
    
    const getTransformValue = useCallback((x, y) => {
      const tipX = x + 15;
      const tipY = y + 15;
      const {tooltipFlippedY, rectHeight } = tooltipPosition || {};
      const { startY, endY } = regionCoordinates || {};
      const heatmapInitialImageHeight = heatmapInitialImage?.height || 700;

      if (tooltipFlippedY) {
        const transformRatio = (endY - startY) > (heatmapInitialImageHeight / 1.75) ? 'translateY(-30%)' : 'translateY(-100%)'
        return {
          top: tipY - rectHeight,
          left: tipX + 20,
          transform: `${transformRatio} ${orientation !== 1 ? 'rotate(90deg)' : ''}`
        }
      }

      if (orientation !== 1 && tipX > 410) {
        return {
          left: tipX - 20,
          top: tipY + 20,
          transform: `translateX(-20%) rotate(90deg)`
        }
      }
      return {
        transform: `translate(${tipX}px, ${tipY - 20}px) ${orientation !== 1 ? 'rotate(90deg)' : ''}` 
      }
    }, [heatmapInitialImage?.height, orientation, regionCoordinates, tooltipPosition]);

    const handleCloseTooltip = useCallback(() => {
      const ctx = regionSelectionCanvas?.current?.getContext("2d");
      ctx.clearRect(0, 0, regionSelectionCanvas?.current?.width, regionSelectionCanvas?.current?.height);
      dragStateRef.current = 'idle';
      setTooltipValues(null);
    }, []);

    useEffect(() => {
      heatmapRef.current = null;
    }, []);

    useEffect(() => {
      heatmapRef.current = Heatmap.create({
        container: document.querySelector('#heatmap-image'),
      });
      return () => {
        heatmapRef.current = null;
      };
    }, []);

    useEffect(() => {
      if (heatmapRef.current) {
        scaleHeatMap();
        handleImageLoaded();
      }
    }, [orientation, scaleHeatMap]);

    useEffect(() => {
      if (heatmapRef.current && heatmapGesturePlot.length) {
        const [maxObject = {}] = heatmapGesturePlot || [];
        if (maxObject?.value) {
          const defaultMaxValue = round(0.5 * maxObject.value);
          setHeatmapMaxValue(maxObject.value);
          setHeatmapMax(defaultMaxValue);
        }
      }
    }, [heatmapGesturePlot]);

    useEffect(() => {
      if (heatmapRef.current && heatmapGesturePlot.length) {
        const [maxObject = {}] = heatmapGesturePlot || [];
        const max = Math.abs(heatmapMax || round(0.5 * maxObject.value));
        const maxV = Math.abs(heatmapMax);
        heatmapRef.current.setData({
          max,
          min: 0,
          data: heatmapGesturePlot.length ? heatmapGesturePlot : []
        });

        if (maxV > 0) {
          heatmapRef.current.setDataMax(maxV);
        }
      }
    }, [heatmapGesturePlot, heatmapMax]);

    useEffect(() => {
      if (heatmapRef.current)
        heatmapRef.current.configure({
          maxOpacity: heatmapOpacity / 100,
          minOpacity: heatmapOpacity / 100 - 0.5,
          radius: 30,
        });
    }, [heatmapOpacity]);

    useEffect(() => {
      if (heatmapRef.current && heatmapGesturePlot.length) {
        tooltipHandler();
        regionSelection();
      }
    }, [regionSelection, tooltipHandler, heatmapGesturePlot]);

    useEffect(() => {
      if (heatmapGesturePlot?.length < 1) return;
      const { startX, startY, endX, endY } = regionCoordinates || {};
      if (startX && startY && endX && endY) {
        if((endX - startX < 0) || (endX - startX < 0 && endY - startY < 0)) {
          updateAreaTooltip(startX, endY, areaSpecificHeatmapGestures?.data?.[0]);
          return;
        }
        updateAreaTooltip(endX, endY, areaSpecificHeatmapGestures?.data?.[0]);
      }   
    }, [areaSpecificHeatmapGestures, isLoading, regionCoordinates, heatmapGesturePlot, updateAreaTooltip])

    return (
      <HeatmapScreenStyled bottomBarClassFlag={bottomBarClassFlag}>
        {isLoading ? (
          <ReactLoader fullscreen={true} />
        ) : (
          !isLoading && heatmapGesturePlot &&
          !heatmapGesturePlot.length && (
            <ErrorTextStyled>
              <InfoCircleOutlined className="info-cirle-heatmap" />
              <strong className="error-text">{noGestureErrorMessage}</strong>
            </ErrorTextStyled>
          )
        )}
        <div
          id="heatmap-image-wrapper"
          className={classNames('heatmap-image-map-wrapper', {
            'heatmap-landscape': orientation === 0,
          })}
        >
          <HeatmapImageStyled
            imageLoaded={imageLoaded}
            id="heatmap-image"
            width={heatmapInitialImage?.width || 480}
            height={heatmapInitialImage?.height || 700}
            data-intercom-target="Heatmap Slides"
            heatmapGesturePlotLen={heatmapGesturePlot.length}
          >
            <span id='tooltip' />
            <Swiper {...params} ref={swiperRef}>
              {heatmapScreenShots?.map((x, i) => (
                <div
                  key={i}
                  className={classNames({ 'no-screenshot': !x.image })}
                >
                  {x.image ? (
                    <ImageStyled
                      alt=""
                      src={x.image}
                      imageOpacity={imageOpacity / 100}
                    />
                  ) : (
                    <span
                      className={classNames({
                        'no-image-landscape': orientation === 0,
                      })}
                    >
                      <WarningOutlined /> <p>Screenshot not taken</p>
                    </span>
                  )}
                </div>
              ))}
            </Swiper>
            {heatmapScreenShotsLen && (
              <button
                type="button"
                onClick={() => swipeHandler('left')}
                className="swiper-button-prev"
                data-intercom-target="Heatmap Prev"
              >
                <LeftOutlined />
              </button>
            )}
            {heatmapScreenShotsLen && (
              <button
                type="button"
                onClick={() => swipeHandler('right')}
                className="swiper-button-next"
                data-intercom-target="Heatmap next"
              >
                <RightOutlined />
              </button>
            )}
            {tooltipValues?.x && tooltipValues?.y ?
              <HeatmapCanvasTooltip
                ref={heatmapCanvasTooltipRef}
                heatmapRegionSelectionEnabled={dragStateRef.current === 'drawn'}
                style={getTransformValue(tooltipValues?.x, tooltipValues?.y)}
              >
                <HeatmapTooltipContent
                  heatmapRegionSelectionEnabled={dragStateRef.current === 'drawn'}
                  isTooltipMetricLoading={isTooltipMetricLoading}
                  nearestPointValues={tooltipValues}
                  handleCloseTooltip={handleCloseTooltip}
                />
              </HeatmapCanvasTooltip> : null}
            <RegionSelectionCanvas
              ref={regionSelectionCanvas}
              width={heatmapInitialImage?.width || 480}
              height={heatmapInitialImage?.height || 700}
            />
          </HeatmapImageStyled>
        </div>
      </HeatmapScreenStyled>
    );
  }
);

export default HeatmapImageMap;