import { useMemo, useCallback, useEffect } from 'react';
import Router from 'next/router';

import { useSelector, useDispatch } from 'react-redux';

import { trackPageViews } from 'redux/actions/trackingReport';
import { urlSegmentEncoder } from 'Utils/helpers/urlSegmentEncoder';
import { screensParentType } from 'components/features/heatmaps/constants';

export const useScreenTableHelper = () => {
  const {
    urlReducer: { appId, screenpage = 1, screenname, parentType },
    appFilter: {
      heatmap: { segment },
    },
  } = useSelector((state) => state);
  const screenPageNumber = useMemo(() => Number(screenpage), [screenpage]);

  const dispatch = useDispatch();

  // while we integrate server side pagination, we need tyo move this logic to its parent if possible, it shoould not be related to table
  const trackEvents = useCallback(
    (selectedPage) => {
      dispatch(
        trackPageViews(null, {
          eventName: 'hm_navigate_screen_table',
          track_type: 'event',
          eventProperty: {
            'resulting page': selectedPage,
          },
        })
      );
    },
    [dispatch]
  );

  const handlePagination = useCallback(
    (currentPage) => {
      trackEvents(currentPage);
      let url = `app/${appId}/screens/list/${currentPage}?`;
      url = urlSegmentEncoder(url, segment);
      Router.push(
        `/integration?appId=${appId}&parentType=${screensParentType}&screenpage=${currentPage}`,
        url
      );
    },
    [appId, segment, trackEvents]
  );

  // Function to split the array into groups of a specified size
  function chunkArray(array, chunkSize) {
    const result = [];
    for (let i = 0; i < array.length; i += chunkSize) {
      result.push(array.slice(i, i + chunkSize));
    }
    return result;
  }

  // handles pagination stick on back navigation from screen details page
  useEffect(() => {
    if (parentType !== 'heatmapsList') return;
    !screenname && handlePagination(screenPageNumber || 1);
  }, [screenname, screenPageNumber, parentType]);

  return {
    handlePagination,
    chunkArray,
  };
};
