
import React, { useMemo } from 'react';
import { useSelector } from 'react-redux';

const useScreenTooltip = (originalScreenName) => {
  const screenRenamedList = useSelector((state) => state.screenRenamedList);
  const renamedScreenName = screenRenamedList[originalScreenName];
  const screename = renamedScreenName || originalScreenName;
  const tooltipElement = useMemo(() => {
    let screenTitle = <span>{originalScreenName}</span>;
    if (renamedScreenName)
      screenTitle = (
        <span>
          <strong>Screen name:</strong>
          <br /> {renamedScreenName} <br />
          <strong>Original screen name:</strong>
          <br />
          {originalScreenName}
        </span>
      );
    return screenTitle;
  }, [renamedScreenName, originalScreenName]);
  return { tooltipElement, renamedScreenName: screename };
};
export default useScreenTooltip;
