import React, { memo, useMemo } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { quickGestureOptions } from 'components/features/heatmaps/constants';
import { useHeatmapContext } from 'components/features/heatmaps/Context/HeatmapContext';
import {
  FilterTitleStyled,
  FilterStyled,
  QuickGestureStyled,
} from 'components/features/heatmaps/HeatmapDetails/HeatmapStyled';
import { trackPageViews } from 'redux/actions/trackingReport';

const QuickGestureSelect = memo(() => {
  const { setQuickGestureOptions, deviceClass, gestureTypes } = useHeatmapContext();
  const {
    appFilter: { heatmap: { segment }},
    urlReducer: {screenname}
  } = useSelector((state) => state);
  const dispatch = useDispatch();

  // const options = useMemo(() => deviceClass.toLowerCase().includes('android')
  //   ? [...quickGestureOptions]
  //   : quickGestureOptions.map(gestureOption => ({
  //     ...gestureOption,
  //     ...(gestureOption.value === 'isresponsive' && { disabled: true })
  //   })), [segment, deviceClass]);

  const options = useMemo(() => deviceClass.toLowerCase().includes('android')
    ? [...quickGestureOptions]
    : quickGestureOptions.filter(item => item.value !== 'isresponsive')
    , [segment, deviceClass]);

  const trackEvents = (gestureOptionsVal, gestoreTypesValues) => {
    dispatch(trackPageViews(null, {
      eventName: 'hm_filter_change',
      track_type: 'event',
      eventProperty: {
        filters: gestureOptionsVal,
        gestures: gestoreTypesValues,
        screenname,
      }
    }))
  }

  const handleQuickGestureOptions = (checkedValues) => {
    setQuickGestureOptions(checkedValues);
    trackEvents(checkedValues, gestureTypes)
  }
  
  return (
    <FilterStyled data-intercom-target="Quick Filter">
      <FilterTitleStyled>Show only</FilterTitleStyled>
      <QuickGestureStyled options={options} onChange={handleQuickGestureOptions} />
    </FilterStyled>
  );
});

export default QuickGestureSelect;
