import { useSelector } from 'react-redux';

export const useScreenNameUrlSuffix = ({ screenname: screenNameArg } = {}) => {
  let replacedScreenName = '';
  let screenNameUrlSuffix = '';
  const {
    appFilter: {
      heatmap: { segment },
      dateSegment,
    },
    urlReducer: { screenname: screenNameQuery },
  } = useSelector(({ appFilter, urlReducer }) => ({
    appFilter,
    urlReducer,
  }));
  const segmentDateFilter = [...segment, ...[dateSegment]];
  const screenName = screenNameArg || screenNameQuery;
  if (screenName) {
    // replacedScreenName = screenName.includes('/')
    //   ? screenName.split('/').join('')
    //   : screenName;
    replacedScreenName = screenName; // Commenting the above code because of CX-1498 where we are considering '/' as an acceptable character in case the character comes from SDK itself
    screenNameUrlSuffix = segmentDateFilter.length
      ? `&screenname=${encodeURIComponent(screenName)}`
      : `?screenname=${encodeURIComponent(screenName)}`;
  }
  return { screenNameUrlSuffix, replacedScreenName };
};
