/* eslint-disable react/jsx-props-no-spreading */
import React, { useCallback, useMemo, useState } from "react";
import { Button, Checkbox, Dropdown } from "antd";
import { DragDropContext, Draggable, Droppable } from "react-beautiful-dnd";
import { getItemStyle, getListStyle, reorder, sortVisibleArrays } from "Utils/helpers/SessionUtils";
import { ColumnIconSVG } from "components/svg_files";
import styled from "styled-components";
import useLocalStorage from "hooks/useLocalStorage";

import LoaderAdvanced from "components/common/LoaderAdvanced";

import { ButtonWrapper, MenuOutlinedWrapper } from "components/common/ColumnUpdate/styles";
import { useIsAppType } from "hooks/useIsAppType";
import { useDispatch } from "react-redux";
import { trackPageViews } from "redux/actions/trackingReport";

const ColumnOrderMenu = styled.div`
  max-height: 420px;
  overflow: auto;
  box-shadow:none;
  padding: 15px 10px 0!important;
`

const ColumnUpdate = ({ updateScreenHeaders, defaultHeaders }) => {
  const [dropdownVisible, setDropdownVisibility] = useState(false);

  const handleVisibleChange = (flag) => setDropdownVisibility(flag);

  return (
    <Dropdown
        overlayClassName="column-edit-dropdown"
        className="dropdown-btn"
        trigger={['click']}
        onVisibleChange={handleVisibleChange}
        visible={dropdownVisible}
        overlay={
          <LoaderAdvanced show={false}>
            <DropdownColumns
              dropdownVisible={dropdownVisible}
              setDropdownVisibility={setDropdownVisibility}
              updateScreenHeaders={updateScreenHeaders}
              defaultHeaders={defaultHeaders}
            />
          </LoaderAdvanced>
        }
      >
        <Button>
          <ColumnIconSVG />
        </Button>
      </Dropdown>
  );
};

export default ColumnUpdate;

export function DropdownColumns({ setDropdownVisibility, updateScreenHeaders, defaultHeaders }) {
  const isWebSDK = useIsAppType('web');
  const [headers, setHeaders] = useLocalStorage(isWebSDK ? "webScreenHeaders" : "screenHeaders");
  const sortedHeaders = useMemo(() => sortVisibleArrays([...headers.filter(obj => obj.attribute !== 'displayName')]), [headers])
  const [screenHeaders, setScreenHeaders] = useState(sortedHeaders);
  const [lastAddedColumn, setLastAddedColumn] = useState(null);

  const dispatch = useDispatch()

  const isColumnDisabled = (column) => column.attribute === 'screenname';

  const onDragEnd = (result) => {
    const destination = screenHeaders[result?.destination?.index];
    if (!result.destination) {
      return;
    }
    if (destination.isDraggable) {
      const res = reorder(screenHeaders, result.source.index, result.destination.index);
      setScreenHeaders(res);
    }
  }

  const handleChange = (e) => {
    const selectedColumn = e.target.value;
    const isCheckedColumn = e.target.checked;
    const updatedArray = screenHeaders.map(sheader => sheader.attribute === selectedColumn ? { ...sheader, isVisible: isCheckedColumn } : sheader);
    setScreenHeaders(updatedArray);
    if (isCheckedColumn) {
      setLastAddedColumn(selectedColumn);
    }
  }

  const handleDoneBtn = useCallback(() => {
    setHeaders(screenHeaders);
    setScreenHeaders(sortVisibleArrays(screenHeaders))
    updateScreenHeaders(screenHeaders);
    setDropdownVisibility(false);
    if (lastAddedColumn) {
      dispatch(trackPageViews(null, {
        eventName: 'wa_column_add',
        track_type: 'event',
        eventProperty: {
          column_name: lastAddedColumn,
        }
      }));
    }
    setLastAddedColumn(null);
  }, [ dispatch, lastAddedColumn, screenHeaders, setDropdownVisibility, setHeaders, updateScreenHeaders ])

  const handleCancelBtn = () => {
    setHeaders(headers);
    setScreenHeaders(sortedHeaders);
    setDropdownVisibility(false);
  }

  const handleResetBtn = () => {
    setHeaders(defaultHeaders);
    setScreenHeaders(defaultHeaders)
    updateScreenHeaders(defaultHeaders);
    setDropdownVisibility(false);
  }
  return (
    <>
      <DragDropContext onDragEnd={onDragEnd}>
        <Droppable droppableId="droppable">
          {(provided, snapshot) => (
            <div className="column-wrapper">
              <ColumnOrderMenu
                ref={provided.innerRef}
                style={getListStyle(snapshot.isDraggingOver)}
              >
                {screenHeaders &&
                  screenHeaders.filter(obj => obj.attribute !== 'displayName').map((obj, index) => (
                    <Draggable
                      key={obj.attribute}
                      draggableId={index}
                      isDragDisabled={isColumnDisabled(obj) || !obj?.isDraggable}
                      disableInteractiveElementBlocking
                      index={index}
                    >
                      {(provided, snapshot) => (
                        <div>
                          <div
                            className="column-edit-items"
                            ref={provided.innerRef}
                            style={getItemStyle(
                              provided.draggableProps.style,
                              snapshot.isDraggingOver
                            )}
                            {...provided.dragHandleProps}
                            {...provided.draggableProps}
                          >
                            <Checkbox
                              checked={obj.isVisible}
                              value={obj.attribute}
                              disabled={isColumnDisabled(obj)}
                              onChange={handleChange}
                            >
                              {obj.title} {obj.subTitle ? obj.subTitle : ''}
                            </Checkbox>
                            {obj.isDraggable && (
                              <a href="#!" className="movable-handle">
                                <MenuOutlinedWrapper />
                              </a>
                            )}
                          </div>
                          {provided.placeholder}
                        </div>
                      )}
                    </Draggable>
                  ))}
                {provided.placeholder}
              </ColumnOrderMenu>
            </div>
          )}
        </Droppable>
      </DragDropContext>
      <ButtonWrapper>
          <Button
            type="link"
            className="reset-btn"
            onClick={() => {
              handleCancelBtn();
              handleResetBtn();
            }}
          >
            Reset
          </Button>
          <Button
            type="primary"
            className="done-btn"
            onClick={handleDoneBtn}
          >
            Apply
          </Button>
      </ButtonWrapper>
    </>
  )

}
