import { useEffect, useMemo, useState } from 'react';
import { useQuery } from 'react-query';
import { RootStateOrAny, useSelector } from 'react-redux';
import { webAnalyticsMenu, webStatMenuKeys } from 'components/features/issues/variables';
import { getTimezoneOffset } from 'Utils/DateConversion/dateConversionUtils';
import { TScreenTimeType } from '../WebScreenAnalytics';
import HeatmapApi from '../apis';

const useScreenGraphAPI = (screenTimeType: TScreenTimeType) => {
    const {
        currentAppReducer: { _id: appId },
        appFilter: {
            heatmap: { segment: heatmapSegment },
            dateSegment,
        }
    } = useSelector((state: RootStateOrAny) => state);

    const [selectedStat, setSelectedStat] = useState('screen_count');
    const [selectedGraphType, setSelectedGraphType] = useState('screen_top_five');

    useEffect(() => {
        if (selectedStat && selectedGraphType) {
            const validGraphTypes = webStatMenuKeys[selectedStat as keyof typeof webStatMenuKeys];
            if (validGraphTypes && !validGraphTypes.includes(selectedGraphType)) {
                setSelectedGraphType(validGraphTypes[0]);
            }
        }
    }, [selectedStat, selectedGraphType, setSelectedGraphType])

    const screenTimeSelected = useMemo(() => selectedStat === 'screen_time', [selectedStat])

    const payloadSelectedStat = useMemo(() => {
        if (screenTimeSelected) {
            return 'screen_duration'
        }
        return selectedStat;
    }, [screenTimeSelected, selectedStat])

    const groupListAttr = useMemo(() => {
        if (selectedGraphType === 'device_type') {
            return 'device_type'
        }

        if (selectedGraphType === 'screen_period_day') {
            return 'screen_period_day'
        }

        if (selectedGraphType === 'event_name') {
            return 'event_name'
        }

        return 'screen_name'
    }, [selectedGraphType])

    const timeOperator = useMemo(() => {
        if (screenTimeSelected) {
            if( screenTimeType === 'medianTime') {
                return 'median'
            }
            return 'avg'
        }
        return ''
    }, [screenTimeSelected, screenTimeType])

    const getGraphPayload = useMemo(() => {
        return (
            {
                appid: appId,
                date_range: dateSegment,
                mega_filters: heatmapSegment,
                aggregation_list: [
                    {
                        attribute: payloadSelectedStat,
                        table: "screenvisit",
                        operator: timeOperator,
                    }
                ],
                group_list: [
                    {
                        // display: webAnalyticsMenu.find(item => item.key === selectedGraphType)?.name,
                        type: selectedGraphType === 'screen_period_day' ? 'date' : 'str',
                        period: selectedGraphType === 'screen_period_day' ? 86400 : undefined,
                        table: "screenvisit",
                        attribute: groupListAttr,
                        max_group_number: 5,
                        show_others: false,
                        ascending: selectedGraphType === 'screen_low_engagement',
                        time_zone_offset: selectedGraphType === 'screen_period_day' ? getTimezoneOffset(dateSegment.tz, new Date()) : undefined,
                    }
                ],
                series_plot_options: {
                    type: selectedGraphType === 'screen_period_day' ? 'line' : "bar"
                },
                is_landing: selectedGraphType === 'screen_top_five_landing',
                is_exit: selectedGraphType === 'screen_top_five_exit',
            }
        )
    }, [appId, dateSegment, groupListAttr, heatmapSegment, payloadSelectedStat, selectedGraphType, timeOperator]);

    const { data: screenGraph, isLoading: isGraphLoading } = useQuery(
        ['screen_graph', getGraphPayload],
        () => HeatmapApi.fetchHeatmapGraph(getGraphPayload),
        {
            retry: 2,
            enabled: !!getGraphPayload && !!appId,
            cacheTime: 0,
        }
    );

    return {
        screenGraph,
        isGraphLoading,
        selectedStat,
        selectedGraphType,
        setSelectedStat,
        setSelectedGraphType,
    };
};

export default useScreenGraphAPI;
